    public mutating func removeCustomButton(id: UUID) {
        customButtons.removeAll { $0.id == id }
        elements.removeAll { $0.id == id }
    }

    public mutating func resetButtonLayout() {
        buttonCustomizations.removeAll()
        customButtons.removeAll()
        elements.removeAll()
    }

    private func firstAvailableCustomSlot() -> GameButton? {
        GameButton.customSlots.first { slot in
            !customButtons.contains { $0.mappedButton == slot }
        }
    }

    public var usesFreeformLayout: Bool {
        !elements.isEmpty
            || customButtons.contains { !$0.layout.isHidden }
            || buttonCustomizations.values.contains { $0.normalized.needsFreeformLayout }
    }

    public func element(for id: UUID) -> KeypadElement? {
        normalized.elements.first { $0.id == id }
    }

    public func element(for identity: GamepadControlIdentity) -> KeypadElement? {
        switch identity {
        case .builtin(let button):
            return normalized.elements.first { $0.builtInButton == button }
        case .custom(let id):
            return normalized.elements.first { $0.id == id }
        case .system, .controlBarItem:
            return nil
        }
    }

    public func elementID(for identity: GamepadControlIdentity) -> UUID? {
        element(for: identity)?.id
    }

    public func identity(forElementID elementID: UUID) -> GamepadControlIdentity? {
        guard let element = element(for: elementID) else { return nil }
        if let builtInButton = element.builtInButton { return .builtin(builtInButton) }
        return .custom(element.id)
    }

    public func topBarActivationFrame(in canvasSize: CGSize) -> CGRect {
        guard canvasSize.width > 1, canvasSize.height > 1 else { return .null }
        let controls = GamepadLayoutResolver.preferredControls(for: normalized, in: canvasSize)
        return controls.first { $0.id == .system(.topBarActivation) }?.frame ?? .null
    }

    public static func normalizedControlBarItems(_ items: [GamepadControlBarItem]) -> [GamepadControlBarItem] {
        var seen = Set<GamepadControlBarItem>()
        var normalizedItems: [GamepadControlBarItem] = []
        normalizedItems.reserveCapacity(items.count)
        for item in items where seen.insert(item).inserted {
            normalizedItems.append(item)
        }
        return normalizedItems
    }

    private static func normalizedControlBarItemCustomizations(
        _ customizations: [GamepadControlBarItemCustomization],
        for normalizedItems: [GamepadControlBarItem]
    ) -> [GamepadControlBarItemCustomization] {
        let workspace = ControlBarCustomizationNormalizationWorkspace(capacity: normalizedItems.count)
        workspace.recordLatestNormalized(customizations)
        workspace.appendVisibleItems(normalizedItems)
        return workspace.result
    }

    private final class ControlBarCustomizationNormalizationWorkspace {
        private var latestAppearance: [GamepadControlBarItem: GamepadControlBarItemCustomization] = [:]
        private(set) var result: [GamepadControlBarItemCustomization] = []

        init(capacity: Int) {
            result.reserveCapacity(capacity)
        }

        func recordLatestNormalized(_ customizations: [GamepadControlBarItemCustomization]) {
            for customization in customizations {
                latestAppearance[customization.item] = customization.normalized
            }
        }

        func appendVisibleItems(_ items: [GamepadControlBarItem]) {
            for item in items {
                guard let customization = latestAppearance[item], !customization.appearance.isDefault else { continue }
                result.append(customization)
            }
        }
    }

    public func controlBarItemCustomization(for item: GamepadControlBarItem) -> GamepadButtonCustomization {
        controlBarItemCustomizations.last { $0.item == item }?.normalized.appearance ?? .defaultValue
    }

    public mutating func setControlBarItemCustomization(_ appearance: GamepadButtonCustomization, for item: GamepadControlBarItem) {
        controlBarItemCustomizations.removeAll { $0.item == item }
        let normalizedAppearance = GamepadControlBarItemCustomization(item: item, appearance: appearance).normalized.appearance
        if !normalizedAppearance.isDefault {
            controlBarItemCustomizations.append(GamepadControlBarItemCustomization(item: item, appearance: normalizedAppearance))
        }
    }

    public mutating func applyControlBarAppearancePatch(
        _ patch: GamepadControlBarAppearancePatch,
        for item: GamepadControlBarItem
    ) throws {
        guard Self.normalizedControlBarItems(controlBarItems).contains(item) else {
            throw GamepadControlBarAppearancePatchError.itemNotPresent
        }
        setControlBarItemCustomization(patch.appearance, for: item)
    }

    public mutating func addControlBarItem(_ item: GamepadControlBarItem, at index: Int? = nil) {
        var items = Self.normalizedControlBarItems(controlBarItems)
        guard !items.contains(item) else { return }
        let insertionIndex = min(max(index ?? items.count, 0), items.count)
        items.insert(item, at: insertionIndex)
        controlBarItems = items
    }

    public mutating func removeControlBarItem(_ item: GamepadControlBarItem) {
        controlBarItems.removeAll { $0 == item }
        controlBarItemCustomizations.removeAll { $0.item == item }
    }

    public mutating func moveControlBarItem(_ item: GamepadControlBarItem, to index: Int) {
        var items = Self.normalizedControlBarItems(controlBarItems)
        guard let sourceIndex = items.firstIndex(of: item) else { return }
        items.remove(at: sourceIndex)
        items.insert(item, at: min(max(index, 0), items.count))
        controlBarItems = items
    }

    public mutating func resetControlBarItemAppearance(_ item: GamepadControlBarItem) {
        controlBarItemCustomizations.removeAll { $0.item == item }
    }

    public mutating func resetControlBar() {
        controlBarItems = Self.defaultControlBarItems
        controlBarItemCustomizations.removeAll()
    }

    private mutating func upsertElementMirror(for customButton: GamepadCustomButton, migratesLegacySlot: Bool) {
        let normalizedButton = customButton.normalized
        let existing = elements.first { $0.id == normalizedButton.id }?.normalized
        let element = KeypadElement(
            id: normalizedButton.id,
            label: normalizedButton.visualLabel(fallback: visualLabel(for: normalizedButton.mappedButton)),
            kind: normalizedButton.controlKind,
            layout: normalizedButton.layout,
            builtInButton: nil,
            legacySlot: migratesLegacySlot ? normalizedButton.mappedButton : existing?.legacySlot,
            visualRole: normalizedButton.visualRole ?? existing?.visualRole,
            output: existing?.output,
            partOutputs: existing?.partOutputs ?? [:],
            joystickMapping: normalizedButton.joystickMapping,
            joystickOutputSettings: normalizedButton.joystickOutputSettings,
            triggerSettings: normalizedButton.triggerSettings,
            trackpadSettings: normalizedButton.trackpadSettings
        ).normalized(layoutIsAlreadyNormalized: true)
        if let index = elements.firstIndex(where: { $0.id == element.id }) {
            elements[index] = element
        } else {
            elements.append(element)
        }
    }

    private func synchronizedElements(migratesLegacySlots: Bool, controlsAreNormalized: Bool = false) -> [KeypadElement] {
        let existing = synchronizedElementIndexes(controlsAreNormalized: controlsAreNormalized)
        var synchronized: [KeypadElement] = []
        var seenIDs = Set<UUID>()
        appendSynchronizedBuiltInElements(
            to: &synchronized,
            seenIDs: &seenIDs,
            existingByButton: existing.byButton,
            controlsAreNormalized: controlsAreNormalized
        )
        appendSynchronizedCustomElements(
            to: &synchronized,
            seenIDs: &seenIDs,
            existingByID: existing.byID,
            migratesLegacySlots: migratesLegacySlots,
            controlsAreNormalized: controlsAreNormalized
        )
        return synchronized
    }

    private func synchronizedElementIndexes(
        controlsAreNormalized: Bool
    ) -> (byID: [UUID: KeypadElement], byButton: [GameButton: KeypadElement]) {
        var byID: [UUID: KeypadElement] = [:]
        var byButton: [GameButton: KeypadElement] = [:]
        for element in elements {
            let metadata = controlsAreNormalized ? element.synchronizationMetadata : element.normalized
            byID[metadata.id] = metadata
            if let builtInButton = metadata.builtInButton {
                byButton[builtInButton] = metadata
            }
        }
        return (byID, byButton)
    }

    private func appendSynchronizedBuiltInElements(
        to synchronized: inout [KeypadElement],
        seenIDs: inout Set<UUID>,
        existingByButton: [GameButton: KeypadElement],
        controlsAreNormalized: Bool
    ) {
        for button in GameButton.builtInControls {
            let layout = controlsAreNormalized
                ? (buttonCustomizations[button] ?? .defaultValue)
                : buttonCustomization(for: button)
            guard !layout.isHidden else { continue }
            let existing = existingByButton[button]
            let id = existing?.id ?? KeypadElement.builtInID(for: button)
            guard seenIDs.insert(id).inserted else { continue }
            synchronized.append(
                KeypadElement(
                    id: id,
                    label: visualLabel(for: button),
                    kind: .button,
                    layout: layout,
                    builtInButton: button,
                    legacySlot: existing?.legacySlot ?? button,
                    visualRole: existing?.visualRole,
                    output: existing?.output,
                    partOutputs: existing?.partOutputs ?? [:]
                ).normalized(layoutIsAlreadyNormalized: true)
            )
        }
    }

    private func appendSynchronizedCustomElements(
        to synchronized: inout [KeypadElement],
        seenIDs: inout Set<UUID>,
        existingByID: [UUID: KeypadElement],
        migratesLegacySlots: Bool,
        controlsAreNormalized: Bool
    ) {
        for customButton in customButtons {
            let normalizedButton = controlsAreNormalized ? customButton : customButton.normalized
            let existing = existingByID[normalizedButton.id]
            guard seenIDs.insert(normalizedButton.id).inserted else { continue }
            synchronized.append(
                KeypadElement(
                    id: normalizedButton.id,
                    label: normalizedButton.visualLabel(fallback: visualLabel(for: normalizedButton.mappedButton)),
                    kind: normalizedButton.controlKind,
                    layout: normalizedButton.layout,
                    builtInButton: nil,
                    legacySlot: migratesLegacySlots ? normalizedButton.mappedButton : existing?.legacySlot,
                    visualRole: normalizedButton.visualRole ?? existing?.visualRole,
                    output: existing?.output,
                    partOutputs: existing?.partOutputs ?? [:],
                    joystickMapping: normalizedButton.joystickMapping,
                    joystickOutputSettings: normalizedButton.joystickOutputSettings,
                    triggerSettings: normalizedButton.triggerSettings,
                    trackpadSettings: normalizedButton.trackpadSettings
                ).normalized(layoutIsAlreadyNormalized: true)
            )
        }
    }

    public var normalized: GamepadCustomization {
        var copy = self
        copy.normalizeInPlace()
        return copy
    }

    mutating func normalizeInPlace() {
        normalizeBackgroundInPlace()
        normalizeArtworkInPlace()
        normalizeLabelsInPlace()
        normalizeBuiltInControlsInPlace()
        normalizeCustomControlsInPlace()
        normalizeElementsInPlace()
        normalizeControlBarInPlace()
        normalizeDesignInPlace()
    }

    private mutating func normalizeBackgroundInPlace() {
        deviceCanvas = deviceCanvas.normalized
        backgroundLightColor = backgroundLightColor?.normalized
        backgroundDarkColor = backgroundDarkColor?.normalized
        backgroundFillStyle = backgroundFillStyle?.normalized
        backgroundLightFillStyle = backgroundLightFillStyle?.normalized
        backgroundDarkFillStyle = backgroundDarkFillStyle?.normalized
    }

    private mutating func normalizeArtworkInPlace() {
        var artworkByID: [String: ThumbleSkinArtworkLayer] = [:]
        for layer in artworkLayers {
            if let normalizedLayer = layer.normalized {
                artworkByID[normalizedLayer.id] = normalizedLayer
            }
        }
        artworkLayers = artworkByID.values
            .filter { !$0.isHidden }
            .sorted {
                if $0.plane != $1.plane { return $0.plane.rawValue < $1.plane.rawValue }
                if $0.zIndex != $1.zIndex { return $0.zIndex < $1.zIndex }
                return $0.id < $1.id
            }
    }

    private mutating func normalizeLabelsInPlace() {
        var normalizedLabels: [GameButton: String] = [:]
        normalizedLabels.reserveCapacity(labelOverrides.count)
        for (button, label) in labelOverrides {
            let normalizedLabel = normalizedGamepadLabel(label)
            if !normalizedLabel.isEmpty {
                normalizedLabels[button] = normalizedLabel
            }
        }
        labelOverrides = normalizedLabels
    }

    private mutating func normalizeBuiltInControlsInPlace() {
        var normalizedControls: [GameButton: GamepadButtonCustomization] = [:]
        normalizedControls.reserveCapacity(buttonCustomizations.count)
        for (button, customization) in buttonCustomizations {
            let normalizedCustomization = customization.normalized
            if !normalizedCustomization.isDefault {
                normalizedControls[button] = normalizedCustomization
            }
        }
        buttonCustomizations = normalizedControls
    }

    private mutating func normalizeCustomControlsInPlace() {
        var seenCustomButtonIDs = Set<UUID>()
        var normalizedCustomButtons: [GamepadCustomButton] = []
        var joystickCount = 0
        var triggerCount = 0
        var trackpadCount = 0
        for customButton in customButtons {
            let normalizedCustomButton = customButton.normalized
            guard seenCustomButtonIDs.insert(normalizedCustomButton.id).inserted else { continue }
            if normalizedCustomButton.isJoystick {
                guard joystickCount < Self.maximumJoysticks else { continue }
                joystickCount += 1
            } else if normalizedCustomButton.isTrigger {
                guard triggerCount < Self.maximumTriggers else { continue }
                triggerCount += 1
            } else if normalizedCustomButton.isTrackpad {
                guard trackpadCount < Self.maximumTrackpads else { continue }
                trackpadCount += 1
            }
            normalizedCustomButtons.append(normalizedCustomButton)
            if normalizedCustomButtons.count >= Self.maximumCustomButtons { break }
        }
        customButtons = normalizedCustomButtons
    }

    private mutating func normalizeElementsInPlace() {
        elements = synchronizedElements(
            migratesLegacySlots: elements.isEmpty,
            controlsAreNormalized: true
        )
    }

    private mutating func normalizeControlBarInPlace() {
        topBarActivationRegion = topBarActivationRegion.normalized
        if topBarActivationRegion.centerX == nil { topBarActivationRegion.centerX = Self.defaultTopBarActivationRegion.centerX }
        if topBarActivationRegion.centerY == nil { topBarActivationRegion.centerY = Self.defaultTopBarActivationRegion.centerY }
        if topBarActivationRegion.shape == nil { topBarActivationRegion.shape = .capsule }
        controlBarItems = Self.normalizedControlBarItems(controlBarItems)
        controlBarItemCustomizations = Self.normalizedControlBarItemCustomizations(
            controlBarItemCustomizations,
            for: controlBarItems
        )
    }

    private mutating func normalizeDesignInPlace() {
        styleLibrary = styleLibrary.normalized
        assetLibrary = assetLibrary.normalized
        designMetadata = designMetadata?.normalized(availableControls: allControlIdentitiesForDesign)
    }

    public var stampedForLocalUpdate: GamepadCustomization {
        var copy = normalized
        copy.updatedAt = Date.currentMilliseconds
        return copy
    }

    public func hasSamePresentation(as other: GamepadCustomization) -> Bool {
        PresentationComparisonWorkspace(self, other).matches
    }

    private final class PresentationComparisonWorkspace {
        private var lhs: GamepadCustomization
        private var rhs: GamepadCustomization

        init(_ lhs: GamepadCustomization, _ rhs: GamepadCustomization) {
            self.lhs = lhs
            self.rhs = rhs
            normalizeLeft()
            normalizeRight()
        }

        private func normalizeLeft() {
            lhs = lhs.normalized
        }

        private func normalizeRight() {
            rhs = rhs.normalized
        }

        var matches: Bool {
            if !matchesLayoutAndBackground { return false }
            if !matchesControls { return false }
            if !matchesControlBar { return false }
            return matchesDesign
        }

        private var matchesLayoutAndBackground: Bool {
            if lhs.layoutMode != rhs.layoutMode { return false }
            if lhs.controlScale != rhs.controlScale { return false }
            if lhs.colorSchemePreference != rhs.colorSchemePreference { return false }
            if lhs.deviceCanvas != rhs.deviceCanvas { return false }
            if lhs.backgroundLightColor != rhs.backgroundLightColor { return false }
            if lhs.backgroundDarkColor != rhs.backgroundDarkColor { return false }
            if lhs.backgroundFillStyle != rhs.backgroundFillStyle { return false }
            if lhs.backgroundLightFillStyle != rhs.backgroundLightFillStyle { return false }
            if lhs.backgroundDarkFillStyle != rhs.backgroundDarkFillStyle { return false }
            if lhs.artworkLayers != rhs.artworkLayers { return false }
            if lhs.accentStyle != rhs.accentStyle { return false }
            return lhs.showsButtonLabels == rhs.showsButtonLabels
        }

        private var matchesControls: Bool {
            if lhs.labelOverrides != rhs.labelOverrides { return false }
            if lhs.buttonCustomizations != rhs.buttonCustomizations { return false }
            if lhs.customButtons != rhs.customButtons { return false }
            return lhs.elements == rhs.elements
        }

        private var matchesControlBar: Bool {
            if lhs.topBarActivationRegion != rhs.topBarActivationRegion { return false }
            if lhs.controlBarItems != rhs.controlBarItems { return false }
            return lhs.controlBarItemCustomizations == rhs.controlBarItemCustomizations
        }

        private var matchesDesign: Bool {
            if lhs.designMetadata != rhs.designMetadata { return false }
            if lhs.styleLibrary != rhs.styleLibrary { return false }
            return lhs.assetLibrary == rhs.assetLibrary
        }
    }

    public static func defaultVisualLabel(for button: GameButton) -> String {
        switch button {
        case .up: "↑"
        case .down: "↓"
        case .left: "←"
        case .right: "→"
        case .jump: "A"
        case .attack: "B"
        case .dash: "C"
        case .focus: "D"
        case .map: "⇧⌘P"
        case .pause: "Esc"
        case .custom1: "C1"
        case .custom2: "C2"
        case .custom3: "C3"
        case .custom4: "C4"
        case .custom5: "C5"
        case .custom6: "C6"
        case .custom7: "C7"
        case .custom8: "C8"
        }
    }

    private static func resolvedDefaultVisualLabel(for button: GameButton, defaultLabel: String?) -> String {
        let normalizedDefaultLabel = defaultLabel.map(normalizedGamepadLabel) ?? ""
        return normalizedDefaultLabel.isEmpty ? defaultVisualLabel(for: button) : normalizedDefaultLabel
    }

    private enum CodingKeys: String, CodingKey {
        case layoutMode
        case controlScale
        case colorSchemePreference
        case deviceCanvas
        case backgroundLightColor
        case backgroundDarkColor
        case backgroundFillStyle
        case backgroundLightFillStyle
        case backgroundDarkFillStyle
        case artworkLayers
        case accentStyle
        case showsButtonLabels
        case labelOverrides
        case buttonCustomizations
        case customButtons
        case elements
        case topBarActivationRegion
        case controlBarItems
        case controlBarItemCustomizations
        case designMetadata
        case styleLibrary
        case assetLibrary
        case updatedAt
    }
}

public enum GamepadSystemControl: String, Codable, CaseIterable, Identifiable, Sendable {
    case topBarActivation = "top_bar_activation"

    public var id: String { rawValue }

    var displayName: String {
        switch self {
        case .topBarActivation: "Control Bar Toggle"
        }
    }

    var subtitle: String {
        switch self {
        case .topBarActivation: "iPhone control bar toggle hotspot"
        }
    }

    var systemImage: String {
        switch self {
        case .topBarActivation: "arrow.down.to.line.compact"
        }
    }
}

public enum GamepadControlIdentity: Hashable, Identifiable, Sendable {
    case builtin(GameButton)
    case custom(UUID)
    case system(GamepadSystemControl)
    case controlBarItem(GamepadControlBarItem)

    public var id: String {
        switch self {
        case .builtin(let button): "builtin.\(button.rawValue)"
        case .custom(let id): "custom.\(id.uuidString)"
        case .system(let control): "system.\(control.rawValue)"
        case .controlBarItem(let item): "control_bar_item.\(item.rawValue)"
        }
    }
}

struct GamepadResolvedControl: Identifiable, Equatable {
    let id: GamepadControlIdentity
    let elementID: UUID?
    let mappedButton: GameButton
    let label: String
    let normalizedCenter: CGPoint
    let center: CGPoint
    let size: CGSize
    let shape: GamepadButtonShapeStyle
    let rotationDegrees: CGFloat
    let layoutCustomization: GamepadButtonCustomization
    let isCustom: Bool
    let isLocationLocked: Bool
    let controlKind: GamepadCustomControlKind
    let visualRole: GamepadVisualRole
    let joystickMapping: GamepadJoystickMapping?
    let joystickOutputSettings: GamepadJoystickOutputSettings?
    let triggerSettings: GamepadTriggerSettings?
    let trackpadSettings: GamepadTrackpadSettings?

    var isJoystick: Bool {
        controlKind == .joystick
    }

    var isTrigger: Bool {
        controlKind == .trigger
    }

    var isTrackpad: Bool {
        controlKind == .trackpad
    }

    var isText: Bool {
        controlKind == .text
    }

    var isDecoration: Bool {
        controlKind == .decoration || controlKind == .text
    }

    var frame: CGRect {
        CGRect(
            x: center.x - size.width / 2,
            y: center.y - size.height / 2,
            width: size.width,
            height: size.height
        )
    }

    var resolvedHitInsets: GamepadHitInsets {
        layoutCustomization.hitInsets?.normalized ?? .runtimeDefault
    }

    var hitFrame: CGRect {
        let insets = resolvedHitInsets
        return CGRect(
            x: frame.minX - insets.leading,
            y: frame.minY - insets.top,
            width: frame.width + insets.leading + insets.trailing,
            height: frame.height + insets.top + insets.bottom
        )
    }

    var hitCenter: CGPoint {
        CGPoint(x: hitFrame.midX, y: hitFrame.midY)
    }

}

extension GamepadCustomization {
    func resolvedControls(
        in canvasSize: CGSize,
        defaultLabelProvider: ((GameButton) -> String?)? = nil
    ) -> [GamepadResolvedControl] {
        GamepadLayoutResolver.resolvedControls(
            for: self,
            in: canvasSize,
            defaultLabelProvider: defaultLabelProvider
        )
    }

    func nudgedControls(
        _ identities: Set<GamepadControlIdentity>,
        by translation: CGSize,
        in canvasSize: CGSize
    ) -> GamepadCustomization? {
        guard !identities.isEmpty,
              canvasSize.width > 1,
              canvasSize.height > 1,
              abs(translation.width) > 0.001 || abs(translation.height) > 0.001
        else {
            return nil
        }

        let controls = resolvedControls(in: canvasSize)
        let snapshots = controls
            .filter { identities.contains($0.id) && !$0.isLocationLocked }
            .map { GamepadControlNudgeSnapshot(control: $0) }
        guard !snapshots.isEmpty else { return nil }

        let adjustedTranslation = GamepadControlNudgeSolver.adjustedTranslation(
            translation,
            snapshots: snapshots,
            canvasSize: canvasSize
        )
        guard abs(adjustedTranslation.width) > 0.001 || abs(adjustedTranslation.height) > 0.001 else { return nil }

        var next = self
        for snapshot in snapshots {
            let proposedCenter = CGPoint(
                x: snapshot.startCenter.x + adjustedTranslation.width,
                y: snapshot.startCenter.y + adjustedTranslation.height
            )
            let normalizedPosition = GamepadLayoutResolver.normalizedPosition(
                for: proposedCenter,
                visualSize: snapshot.size,
                in: canvasSize
            )
            next.setPosition(normalizedPosition, for: snapshot.identity)
        }

        let normalizedNext = next.normalized
        return normalizedNext == normalized ? nil : normalizedNext
    }

    @discardableResult
    mutating func nudgeControls(
        _ identities: Set<GamepadControlIdentity>,
        by translation: CGSize,
        in canvasSize: CGSize
    ) -> Bool {
        guard let next = nudgedControls(identities, by: translation, in: canvasSize) else { return false }
        self = next
        return true
    }
}

private struct GamepadControlNudgeSnapshot {
    let identity: GamepadControlIdentity
    let startCenter: CGPoint
    let size: CGSize

    init(control: GamepadResolvedControl) {
        identity = control.id
        startCenter = control.center
        size = control.size
    }

    var startFrame: CGRect {
        CGRect(
            x: startCenter.x - size.width / 2,
            y: startCenter.y - size.height / 2,
            width: size.width,
            height: size.height
        )
    }
}

private enum GamepadControlNudgeSolver {
    static func adjustedTranslation(
        _ translation: CGSize,
        snapshots: [GamepadControlNudgeSnapshot],
        canvasSize: CGSize
    ) -> CGSize {
        clampedTranslation(translation, snapshots: snapshots, canvasSize: canvasSize)
    }

    private static func clampedTranslation(
        _ translation: CGSize,
        snapshots: [GamepadControlNudgeSnapshot],
        canvasSize: CGSize
    ) -> CGSize {
        guard !snapshots.isEmpty else { return .zero }
        let frames = snapshots.map(\.startFrame)
        let minXOffset = frames.map { -$0.minX }.max() ?? 0
        let maxXOffset = frames.map { canvasSize.width - $0.maxX }.min() ?? 0
        let minYOffset = frames.map { -$0.minY }.max() ?? 0
        let maxYOffset = frames.map { canvasSize.height - $0.maxY }.min() ?? 0
        return CGSize(
            width: GamepadButtonCustomization.clamp(translation.width, lower: minXOffset, upper: maxXOffset),
            height: GamepadButtonCustomization.clamp(translation.height, lower: minYOffset, upper: maxYOffset)
        )
    }

}

enum GamepadLayoutResolver {
    private static let minimumControlSpacing: CGFloat = 0

    static func resolvedControls(
        for customization: GamepadCustomization,
        in canvasSize: CGSize,
        defaultLabelProvider: ((GameButton) -> String?)? = nil
    ) -> [GamepadResolvedControl] {
        let resolved = preferredControls(
            for: customization,
            in: canvasSize,
            defaultLabelProvider: defaultLabelProvider
        )
        let layerOrder = customization.orderedControlIdentitiesForDesign
        guard !layerOrder.isEmpty else { return resolved }
        let orderLookup = Dictionary(uniqueKeysWithValues: layerOrder.enumerated().map { ($0.element, $0.offset) })
        return resolved.sorted { lhs, rhs in
            if lhs.layoutCustomization.zIndex != rhs.layoutCustomization.zIndex {
                return lhs.layoutCustomization.zIndex < rhs.layoutCustomization.zIndex
            }
            let lhsIndex = orderLookup[lhs.id] ?? Int.max
            let rhsIndex = orderLookup[rhs.id] ?? Int.max
            if lhsIndex == rhsIndex { return lhs.id.id < rhs.id.id }
            return lhsIndex < rhsIndex
        }
    }

    static func preferredControls(
        for customization: GamepadCustomization,
        in canvasSize: CGSize,
        defaultLabelProvider: ((GameButton) -> String?)? = nil
    ) -> [GamepadResolvedControl] {
        guard canvasSize.width > 1, canvasSize.height > 1 else { return [] }

        let builtinControls = GameButton.builtInControls.compactMap { button -> GamepadResolvedControl? in
            let buttonCustomization = customization.buttonCustomization(for: button)
            guard !buttonCustomization.isHidden else { return nil }

            let defaultShape = defaultShape(for: button)
            let shape = buttonCustomization.resolvedShape(defaultShape: defaultShape)
            let baseSize = baseSize(for: button, controlScale: customization.controlScale, in: canvasSize)
            let scaledSize = effectiveSize(
                CGSize(
                    width: baseSize.width * buttonCustomization.widthScale,
                    height: baseSize.height * buttonCustomization.heightScale
                ),
                shape: shape
            )
            let defaultCenter = defaultNormalizedCenter(for: button, layoutMode: customization.layoutMode, visualSize: scaledSize, in: canvasSize)
            let normalizedCenter = CGPoint(
                x: buttonCustomization.centerX ?? defaultCenter.x,
                y: buttonCustomization.centerY ?? defaultCenter.y
            )
            let center = clampedPixelCenter(normalizedCenter, visualSize: scaledSize, in: canvasSize)

            return GamepadResolvedControl(
                id: .builtin(button),
                elementID: KeypadElement.builtInID(for: button),
                mappedButton: button,
                label: customization.visualLabel(for: button),
                normalizedCenter: CGPoint(x: center.x / canvasSize.width, y: center.y / canvasSize.height),
                center: center,
                size: scaledSize,
                shape: shape,
                rotationDegrees: buttonCustomization.rotationDegrees,
                layoutCustomization: buttonCustomization,
                isCustom: false,
                isLocationLocked: buttonCustomization.isLocationLocked,
                controlKind: .button,
                visualRole: customization.elements.first(where: { $0.builtInButton == button })?.visualRole
                    ?? GamepadVisualRole.inferred(for: button, controlKind: .button),
                joystickMapping: nil,
                joystickOutputSettings: nil,
                triggerSettings: nil,
                trackpadSettings: nil
            )
        }

        let customControls = customization.customButtons.compactMap { customButton -> GamepadResolvedControl? in
            let normalizedButton = customButton.normalized
            guard !normalizedButton.layout.isHidden else { return nil }

            let defaultShape: GamepadButtonShapeStyle = if normalizedButton.isJoystick {
                .circle
            } else if normalizedButton.isDecoration {
                .roundedRectangle
            } else {
                defaultShape(for: normalizedButton.mappedButton)
            }
            let shape = normalizedButton.layout.resolvedShape(defaultShape: defaultShape)
            let baseControlSize: CGSize
            if normalizedButton.isJoystick {
                baseControlSize = joystickBaseSize(controlScale: customization.controlScale, in: canvasSize)
            } else if normalizedButton.isTrigger {
                baseControlSize = triggerBaseSize(controlScale: customization.controlScale, in: canvasSize)
            } else if normalizedButton.isTrackpad {
                baseControlSize = trackpadBaseSize(controlScale: customization.controlScale, in: canvasSize)
            } else if normalizedButton.isText {
                baseControlSize = textBaseSize(controlScale: customization.controlScale, in: canvasSize)
            } else if normalizedButton.isDecoration {
                baseControlSize = baseSize(for: .jump, controlScale: customization.controlScale, in: canvasSize)
            } else {
                baseControlSize = baseSize(for: normalizedButton.mappedButton, controlScale: customization.controlScale, in: canvasSize)
            }
            let scaledSize = effectiveSize(
                CGSize(
                    width: baseControlSize.width * normalizedButton.layout.widthScale,
                    height: baseControlSize.height * normalizedButton.layout.heightScale
                ),
                shape: shape
            )
            let normalizedCenter = CGPoint(
                x: normalizedButton.layout.centerX ?? 0.5,
                y: normalizedButton.layout.centerY ?? 0.5
            )
            let center = clampedPixelCenter(normalizedCenter, visualSize: scaledSize, in: canvasSize)

            let fallbackLabel = customization.visualLabel(for: normalizedButton.mappedButton)

            return GamepadResolvedControl(
                id: .custom(normalizedButton.id),
                elementID: normalizedButton.id,
                mappedButton: normalizedButton.mappedButton,
                label: normalizedButton.visualLabel(fallback: fallbackLabel),
                normalizedCenter: CGPoint(x: center.x / canvasSize.width, y: center.y / canvasSize.height),
                center: center,
                size: scaledSize,
                shape: shape,
                rotationDegrees: normalizedButton.layout.rotationDegrees,
                layoutCustomization: normalizedButton.layout,
                isCustom: true,
                isLocationLocked: normalizedButton.layout.isLocationLocked,
                controlKind: normalizedButton.controlKind,
                visualRole: normalizedButton.visualRole
                    ?? GamepadVisualRole.inferred(for: normalizedButton.mappedButton, controlKind: normalizedButton.controlKind),
                joystickMapping: normalizedButton.isJoystick ? (normalizedButton.joystickMapping ?? .movement) : nil,
                joystickOutputSettings: normalizedButton.isJoystick ? (normalizedButton.joystickOutputSettings ?? .defaultValue).normalized : nil,
                triggerSettings: normalizedButton.isTrigger ? (normalizedButton.triggerSettings ?? .defaultValue).normalized : nil,
                trackpadSettings: normalizedButton.isTrackpad ? (normalizedButton.trackpadSettings ?? .defaultValue).normalized : nil
            )
        }

        let systemControls = systemControls(for: customization, in: canvasSize)
        return builtinControls + customControls + systemControls
    }

    private static func systemControls(for customization: GamepadCustomization, in canvasSize: CGSize) -> [GamepadResolvedControl] {
        let layout = customization.topBarActivationRegion.normalized
        guard !layout.isHidden else { return [] }

        let shape = layout.resolvedShape(defaultShape: .capsule)
        let baseControlSize = topBarActivationBaseSize
        let scaledSize = effectiveSize(
            CGSize(
                width: baseControlSize.width * layout.widthScale,
                height: baseControlSize.height * layout.heightScale
            ),
            shape: shape
        )
        let defaultCenter = CGPoint(
            x: GamepadCustomization.defaultTopBarActivationRegion.centerX ?? 0.5,
            y: GamepadCustomization.defaultTopBarActivationRegion.centerY ?? 0.075
        )
        let normalizedCenter = CGPoint(
            x: layout.centerX ?? defaultCenter.x,
            y: layout.centerY ?? defaultCenter.y
        )
        let center = clampedPixelCenter(normalizedCenter, visualSize: scaledSize, in: canvasSize)

        return [
            GamepadResolvedControl(
                id: .system(.topBarActivation),
                elementID: nil,
                mappedButton: .pause,
                label: GamepadSystemControl.topBarActivation.displayName,
                normalizedCenter: CGPoint(x: center.x / canvasSize.width, y: center.y / canvasSize.height),
                center: center,
                size: scaledSize,
                shape: shape,
                rotationDegrees: layout.rotationDegrees,
                layoutCustomization: layout,
                isCustom: false,
                isLocationLocked: layout.isLocationLocked,
                controlKind: .decoration,
                visualRole: .system,
                joystickMapping: nil,
                joystickOutputSettings: nil,
                triggerSettings: nil,
                trackpadSettings: nil
            )
        ]
    }

    private static func textBaseSize(controlScale: GamepadControlScale, in canvasSize: CGSize) -> CGSize {
        let buttonSize = baseSize(for: .jump, controlScale: controlScale, in: canvasSize)
        return CGSize(width: buttonSize.width, height: max(24, buttonSize.height * 0.58))
    }

    static func defaultShape(for button: GameButton) -> GamepadButtonShapeStyle {
        switch button {
        case .map, .pause: .capsule
        default: .roundedRectangle
        }
    }

    static func normalizedPosition(for point: CGPoint, visualSize: CGSize, in canvasSize: CGSize) -> CGPoint {
        let center = clampedPixelCenter(
            CGPoint(x: point.x / max(canvasSize.width, 1), y: point.y / max(canvasSize.height, 1)),
            visualSize: visualSize,
            in: canvasSize
        )
        return CGPoint(x: center.x / canvasSize.width, y: center.y / canvasSize.height)
    }

    static func nonOverlappingFrame(
        for preferredFrame: CGRect,
        avoiding existingFrames: [CGRect],
        in canvasSize: CGSize,
        minimumSpacing: CGFloat = minimumControlSpacing
    ) -> CGRect? {
        let clampedPreferred = clampedFrame(preferredFrame, in: canvasSize)
        guard frameOverlapsAny(clampedPreferred, avoiding: existingFrames, minimumSpacing: minimumSpacing) else {
            return clampedPreferred
        }

        let xCandidates = candidateOrigins(
            preferred: clampedPreferred.minX,
            length: clampedPreferred.width,
            canvasLength: canvasSize.width,
            existingFrames: existingFrames,
            axis: .horizontal,
            minimumSpacing: minimumSpacing
        )
        let yCandidates = candidateOrigins(
            preferred: clampedPreferred.minY,
            length: clampedPreferred.height,
            canvasLength: canvasSize.height,
            existingFrames: existingFrames,
            axis: .vertical,
            minimumSpacing: minimumSpacing
        )

        var bestFrame: CGRect?
        var bestScore = CGFloat.greatestFiniteMagnitude
        let preferredCenter = CGPoint(x: clampedPreferred.midX, y: clampedPreferred.midY)

        for x in xCandidates {
            let dx = (x + clampedPreferred.width / 2) - preferredCenter.x
            let xScore = dx * dx
            guard xScore < bestScore else { break }

            for y in yCandidates {
                let dy = (y + clampedPreferred.height / 2) - preferredCenter.y
                let score = xScore + dy * dy
                guard score < bestScore else { break }

                let candidate = CGRect(
                    x: x,
                    y: y,
                    width: clampedPreferred.width,
                    height: clampedPreferred.height
                )
                guard !frameOverlapsAny(candidate, avoiding: existingFrames, minimumSpacing: minimumSpacing) else { continue }

                bestScore = score
                bestFrame = candidate
            }
        }

        return bestFrame
    }

    static func frameOverlapsAny(
        _ frame: CGRect,
        avoiding existingFrames: [CGRect],
        minimumSpacing: CGFloat = minimumControlSpacing
    ) -> Bool {
        existingFrames.contains { existingFrame in
            framesOverlap(frame, existingFrame, minimumSpacing: minimumSpacing)
        }
    }


    private enum CandidateAxis {
        case horizontal
        case vertical
    }

    private static func candidateOrigins(
        preferred: CGFloat,
        length: CGFloat,
        canvasLength: CGFloat,
        existingFrames: [CGRect],
        axis: CandidateAxis,
        minimumSpacing: CGFloat
    ) -> [CGFloat] {
        var rawValues = [preferred]

        if length >= canvasLength {
            rawValues.append((canvasLength - length) / 2)
        } else {
            rawValues.append(0)
            rawValues.append(canvasLength - length)
        }

        for frame in existingFrames {
            let minValue: CGFloat
            let maxValue: CGFloat
            switch axis {
            case .horizontal:
                minValue = frame.minX
                maxValue = frame.maxX
            case .vertical:
                minValue = frame.minY
                maxValue = frame.maxY
            }

            rawValues.append(minValue - minimumSpacing - length)
            rawValues.append(maxValue + minimumSpacing)
            rawValues.append(minValue)
            rawValues.append(maxValue - length)
        }

        let clampedValues = rawValues
            .map { clampedOrigin($0, length: length, canvasLength: canvasLength) }
            .sorted()
        var uniqueValues: [CGFloat] = []
        uniqueValues.reserveCapacity(clampedValues.count)
        for value in clampedValues {
            guard let lastValue = uniqueValues.last else {
                uniqueValues.append(value)
                continue
            }
            guard abs(lastValue - value) >= 0.5 else { continue }
            uniqueValues.append(value)
        }

        return uniqueValues.sorted { lhs, rhs in
            let lhsDistance = abs(lhs - preferred)
            let rhsDistance = abs(rhs - preferred)
            if abs(lhsDistance - rhsDistance) > 0.001 { return lhsDistance < rhsDistance }
            return lhs < rhs
        }
    }

    private static func framesOverlap(_ lhs: CGRect, _ rhs: CGRect, minimumSpacing: CGFloat) -> Bool {
        lhs.minX < rhs.maxX + minimumSpacing
            && lhs.maxX + minimumSpacing > rhs.minX
            && lhs.minY < rhs.maxY + minimumSpacing
            && lhs.maxY + minimumSpacing > rhs.minY
    }

    private static func clampedFrame(_ frame: CGRect, in canvasSize: CGSize) -> CGRect {
        CGRect(
            x: clampedOrigin(frame.minX, length: frame.width, canvasLength: canvasSize.width),
            y: clampedOrigin(frame.minY, length: frame.height, canvasLength: canvasSize.height),
            width: frame.width,
            height: frame.height
        )
    }

    private static func clampedOrigin(_ origin: CGFloat, length: CGFloat, canvasLength: CGFloat) -> CGFloat {
        guard length < canvasLength else { return (canvasLength - length) / 2 }
        return GamepadButtonCustomization.clamp(origin, lower: 0, upper: max(0, canvasLength - length))
    }

    private static func baseSize(for button: GameButton, controlScale: GamepadControlScale, in canvasSize: CGSize) -> CGSize {
        let isLandscape = canvasSize.width >= canvasSize.height
        let shortestSide = max(1, min(canvasSize.width, canvasSize.height))
        let scale = controlScale.multiplier
        let side = min(86 * scale, max(50 * scale, shortestSide * (isLandscape ? 0.24 : 0.20) * scale))

        switch button {
        case .map:
            return CGSize(width: side * 1.48, height: side * 0.72)
        case .pause:
            return CGSize(width: side * 1.66, height: side * 0.72)
        default:
            return CGSize(width: side, height: side)
        }
    }

    private static func joystickBaseSize(controlScale: GamepadControlScale, in canvasSize: CGSize) -> CGSize {
        let isLandscape = canvasSize.width >= canvasSize.height
        let shortestSide = max(1, min(canvasSize.width, canvasSize.height))
        let scale = controlScale.multiplier
        let side = min(128 * scale, max(82 * scale, shortestSide * (isLandscape ? 0.30 : 0.24) * scale))
        return CGSize(width: side, height: side)
    }

    private static func triggerBaseSize(controlScale: GamepadControlScale, in canvasSize: CGSize) -> CGSize {
        let isLandscape = canvasSize.width >= canvasSize.height
        let shortestSide = max(1, min(canvasSize.width, canvasSize.height))
        let scale = controlScale.multiplier
        let width = min(148 * scale, max(86 * scale, shortestSide * (isLandscape ? 0.30 : 0.24) * scale))
        let height = min(58 * scale, max(34 * scale, shortestSide * (isLandscape ? 0.11 : 0.09) * scale))
        return CGSize(width: width, height: height)
    }

    private static func trackpadBaseSize(controlScale: GamepadControlScale, in canvasSize: CGSize) -> CGSize {
        let isLandscape = canvasSize.width >= canvasSize.height
        let shortestSide = max(1, min(canvasSize.width, canvasSize.height))
        let scale = controlScale.multiplier
        let width = min(230 * scale, max(142 * scale, shortestSide * (isLandscape ? 0.48 : 0.42) * scale))
        let height = min(150 * scale, max(92 * scale, shortestSide * (isLandscape ? 0.28 : 0.24) * scale))
        return CGSize(width: width, height: height)
    }

    /// Matches the compact 60×44 pt reveal handle used by the iPhone runtime.
    /// Width and height scaling remain available for intentionally larger hotspots.
    private static let topBarActivationBaseSize = CGSize(width: 60, height: 44)

    private static func effectiveSize(_ size: CGSize, shape: GamepadButtonShapeStyle) -> CGSize {
        size
    }

    private static func defaultNormalizedCenter(
        for button: GameButton,
        layoutMode: GamepadLayoutMode,
        visualSize: CGSize,
        in canvasSize: CGSize
    ) -> CGPoint {
        let isLandscape = canvasSize.width >= canvasSize.height
        let xStep = min(0.18, max(0.08, (visualSize.width * 1.12) / canvasSize.width))
        let yStep = min(0.26, max(0.10, (visualSize.height * 1.12) / canvasSize.height))

        if isLandscape {
            let dPadCenterX: CGFloat = layoutMode == .standard ? 0.18 : 0.82
            let actionCenterX: CGFloat = layoutMode == .standard ? 0.82 : 0.18
            let groupY: CGFloat = 0.56

            switch button {
            case .up: return CGPoint(x: dPadCenterX, y: groupY - yStep)
            case .down: return CGPoint(x: dPadCenterX, y: groupY + yStep)
            case .left: return CGPoint(x: dPadCenterX - xStep, y: groupY)
            case .right: return CGPoint(x: dPadCenterX + xStep, y: groupY)
            case .focus: return CGPoint(x: actionCenterX - xStep * 0.55, y: groupY - yStep * 0.55)
            case .dash: return CGPoint(x: actionCenterX + xStep * 0.55, y: groupY - yStep * 0.55)
            case .attack: return CGPoint(x: actionCenterX - xStep * 0.55, y: groupY + yStep * 0.55)
            case .jump: return CGPoint(x: actionCenterX + xStep * 0.55, y: groupY + yStep * 0.55)
            case .map: return CGPoint(x: 0.43, y: groupY)
            case .pause: return CGPoint(x: 0.57, y: groupY)
            case .custom1, .custom2, .custom3, .custom4, .custom5, .custom6, .custom7, .custom8:
                return CGPoint(x: 0.5, y: groupY)
            }
        } else {
            let dPadY: CGFloat = layoutMode == .standard ? 0.28 : 0.74
            let actionY: CGFloat = layoutMode == .standard ? 0.74 : 0.28
            let xCenter: CGFloat = 0.5
            let portraitXStep = min(0.22, max(0.13, (visualSize.width * 1.16) / canvasSize.width))
            let portraitYStep = min(0.12, max(0.08, (visualSize.height * 1.10) / canvasSize.height))

            switch button {
            case .up: return CGPoint(x: xCenter, y: dPadY - portraitYStep)
            case .down: return CGPoint(x: xCenter, y: dPadY + portraitYStep)
            case .left: return CGPoint(x: xCenter - portraitXStep, y: dPadY)
            case .right: return CGPoint(x: xCenter + portraitXStep, y: dPadY)
            case .focus: return CGPoint(x: xCenter - portraitXStep * 0.55, y: actionY - portraitYStep * 0.75)
            case .dash: return CGPoint(x: xCenter + portraitXStep * 0.55, y: actionY - portraitYStep * 0.75)
            case .attack: return CGPoint(x: xCenter - portraitXStep * 0.55, y: actionY + portraitYStep * 0.75)
            case .jump: return CGPoint(x: xCenter + portraitXStep * 0.55, y: actionY + portraitYStep * 0.75)
            case .map: return CGPoint(x: 0.36, y: 0.51)
            case .pause: return CGPoint(x: 0.64, y: 0.51)
            case .custom1, .custom2, .custom3, .custom4, .custom5, .custom6, .custom7, .custom8:
                return CGPoint(x: 0.5, y: 0.51)
            }
        }
    }

    private static func clampedPixelCenter(_ normalizedCenter: CGPoint, visualSize: CGSize, in canvasSize: CGSize) -> CGPoint {
        let halfWidth = min(canvasSize.width / 2, max(visualSize.width / 2, 1))
        let halfHeight = min(canvasSize.height / 2, max(visualSize.height / 2, 1))
        return CGPoint(
            x: GamepadButtonCustomization.clamp(normalizedCenter.x * canvasSize.width, lower: halfWidth, upper: max(halfWidth, canvasSize.width - halfWidth)),
            y: GamepadButtonCustomization.clamp(normalizedCenter.y * canvasSize.height, lower: halfHeight, upper: max(halfHeight, canvasSize.height - halfHeight))
        )
    }
}

private func normalizedGamepadLabel(_ label: String) -> String {
    let trimmed = label.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return "" }
    return String(trimmed.prefix(gamepadMaximumLabelLength))
}

extension GamepadCustomization {
    func resolvedColorScheme(system systemScheme: ColorScheme) -> ColorScheme {
        colorSchemePreference.resolvedColorScheme(system: systemScheme)
    }

    func backgroundColorValue(for scheme: ColorScheme) -> GamepadRGBAColor {
        keypadBackgroundFillStyle(scheme: scheme).representativeColor.normalized
    }

    func keypadBackgroundColor(scheme: ColorScheme) -> Color {
        backgroundColorValue(for: scheme).swiftUIColor
    }

    func keypadBackgroundFillStyle(scheme: ColorScheme) -> GamepadFillStyle {
        (backgroundFillStyle(for: scheme) ?? .solid(Self.defaultBackgroundColor(for: scheme)))
            .resolvingAssets(in: assetLibrary)
    }

    func backgroundFillStyle(for scheme: ColorScheme) -> GamepadFillStyle? {
        switch scheme {
        case .dark:
            if let backgroundDarkFillStyle { return backgroundDarkFillStyle.normalized }
            if let backgroundFillStyle { return backgroundFillStyle.normalized }
            if let backgroundDarkColor { return .solid(backgroundDarkColor.normalized) }
            return nil
        default:
            if let backgroundLightFillStyle { return backgroundLightFillStyle.normalized }
            if let backgroundFillStyle { return backgroundFillStyle.normalized }
            if let backgroundLightColor { return .solid(backgroundLightColor.normalized) }
            return nil
        }
    }

    func hasCustomBackgroundColor(for scheme: ColorScheme) -> Bool {
        hasCustomBackgroundFill(for: scheme)
    }

    func hasCustomBackgroundFill(for scheme: ColorScheme) -> Bool {
        switch scheme {
        case .dark:
            backgroundDarkFillStyle != nil || backgroundFillStyle != nil || backgroundDarkColor != nil
        default:
            backgroundLightFillStyle != nil || backgroundFillStyle != nil || backgroundLightColor != nil
        }
    }

    mutating func setBackgroundColor(_ color: GamepadRGBAColor?, for scheme: ColorScheme) {
        prepareSchemeSpecificBackgroundFillStorage()
        switch scheme {
        case .dark:
            backgroundDarkColor = color?.normalized
            backgroundDarkFillStyle = nil
        default:
            backgroundLightColor = color?.normalized
            backgroundLightFillStyle = nil
        }
    }

    mutating func setBackgroundFillStyle(_ style: GamepadFillStyle, for scheme: ColorScheme) {
        prepareSchemeSpecificBackgroundFillStorage()
        switch scheme {
        case .dark:
            backgroundDarkFillStyle = style.normalized
            backgroundDarkColor = nil
        default:
            backgroundLightFillStyle = style.normalized
            backgroundLightColor = nil
        }
    }

    mutating func clearBackgroundFill(for scheme: ColorScheme) {
        prepareSchemeSpecificBackgroundFillStorage()
        switch scheme {
        case .dark:
            backgroundDarkColor = nil
            backgroundDarkFillStyle = nil
        default:
            backgroundLightColor = nil
            backgroundLightFillStyle = nil
        }
    }

    mutating func prepareSchemeSpecificBackgroundFillStorage() {
        if let globalFillStyle = backgroundFillStyle?.normalized {
            if backgroundLightFillStyle == nil {
                backgroundLightFillStyle = globalFillStyle
            }
            if backgroundDarkFillStyle == nil {
                backgroundDarkFillStyle = globalFillStyle
            }
            backgroundFillStyle = nil
        }
    }

    static func defaultBackgroundColor(for scheme: ColorScheme) -> GamepadRGBAColor {
        switch scheme {
        case .dark:
            GamepadRGBAColor(red: 0, green: 0, blue: 0, alpha: 1)
        default:
            GamepadRGBAColor(red: 1, green: 1, blue: 1, alpha: 1)
        }
    }
}

enum GamepadCustomizationPersistence {
    static let defaultsKey = "PocketPad.gamepadCustomization.v1"

    static func load() -> GamepadCustomization {
        guard let data = UserDefaults.standard.data(forKey: defaultsKey),
              let decoded = try? JSONDecoder().decode(GamepadCustomization.self, from: data)
        else {
            return .defaultValue
        }
        return decoded.normalized
    }

    static func save(_ customization: GamepadCustomization) {
        guard let data = try? JSONEncoder().encode(customization.normalized) else { return }
        UserDefaults.standard.set(data, forKey: defaultsKey)
    }
}

extension GamepadButtonCustomization {
    func buttonFillStyle(accentStyle: GamepadAccentStyle, isPressed: Bool, scheme: ColorScheme) -> GamepadFillStyle {
        if let fillStyle = fillStyle(for: scheme) {
            return fillStyle.adjustedForPress(isPressed)
        }
        return .solid(GamepadRGBAColor(color: accentStyle.buttonFill(isPressed: isPressed, scheme: scheme), fallback: .defaultValue).normalized)
    }

    func buttonFill(accentStyle: GamepadAccentStyle, isPressed: Bool, scheme: ColorScheme) -> Color {
        buttonFillStyle(accentStyle: accentStyle, isPressed: isPressed, scheme: scheme).representativeColor.swiftUIColor
    }

    func buttonForeground(accentStyle: GamepadAccentStyle, isPressed: Bool, scheme: ColorScheme) -> Color {
        if fillStyle(for: scheme) != nil {
            return buttonFillStyle(accentStyle: accentStyle, isPressed: isPressed, scheme: scheme).representativeColor.foregroundColor
        }
        return accentStyle.buttonForeground(isPressed: isPressed, scheme: scheme)
    }

    func buttonStroke(accentStyle: GamepadAccentStyle, isPressed: Bool, scheme: ColorScheme) -> Color {
        if fillStyle(for: scheme) != nil {
            return buttonFillStyle(accentStyle: accentStyle, isPressed: isPressed, scheme: scheme).representativeColor.strokeColor
        }
        return accentStyle.buttonStroke(isPressed: isPressed, scheme: scheme)
    }

    func joystickKnobFill(accentStyle: GamepadAccentStyle, isPressed: Bool, scheme: ColorScheme) -> Color {
        if let color = joystickKnobColor(for: scheme) {
            return color.adjustedForPress(isPressed).swiftUIColor
        }
        return buttonForeground(accentStyle: accentStyle, isPressed: isPressed, scheme: scheme)
            .opacity(scheme == .dark ? 0.30 : 0.18)
    }

    func joystickKnobStroke(accentStyle: GamepadAccentStyle, isPressed: Bool, scheme: ColorScheme) -> Color {
        if let color = joystickKnobColor(for: scheme) {
            let adjustedColor = color.adjustedForPress(isPressed)
            return adjustedColor.alpha > 0.001 ? adjustedColor.strokeColor : .clear
        }
        return buttonForeground(accentStyle: accentStyle, isPressed: isPressed, scheme: scheme)
            .opacity(0.34)
    }
}

extension GamepadAccentStyle {
    func buttonFill(isPressed: Bool, scheme: ColorScheme) -> Color {
        if isPressed {
            strongColor(scheme: scheme)
        } else {
            softColor(scheme: scheme)
        }
    }

    func buttonForeground(isPressed: Bool, scheme: ColorScheme) -> Color {
        if isPressed {
            Geist.color(.background100, scheme: scheme)
        } else if self == .monochrome || self == .amber {
            Geist.color(.gray1000, scheme: scheme)
        } else {
            strongColor(scheme: scheme)
        }
    }

    func buttonStroke(isPressed: Bool, scheme: ColorScheme) -> Color {
        if self == .monochrome || self == .amber {
            return isPressed ? Geist.color(.grayAlpha600, scheme: scheme) : Geist.color(.grayAlpha400, scheme: scheme)
        }
        return isPressed ? strongColor(scheme: scheme) : borderColor(scheme: scheme)
    }

    private func softColor(scheme: ColorScheme) -> Color {
        switch self {
        case .monochrome: Geist.color(.gray100, scheme: scheme)
        case .blue: Geist.color(.blue100, scheme: scheme)
        case .green: Geist.color(.green100, scheme: scheme)
        case .purple: Geist.color(.purple100, scheme: scheme)
        case .pink: Geist.color(.pink100, scheme: scheme)
        case .amber: Geist.color(.gray100, scheme: scheme)
        }
    }

    private func strongColor(scheme: ColorScheme) -> Color {
        switch self {
        case .monochrome: Geist.color(.gray1000, scheme: scheme)
        case .blue: Geist.color(.blue900, scheme: scheme)
        case .green: Geist.color(.green900, scheme: scheme)
        case .purple: Geist.color(.purple900, scheme: scheme)
        case .pink: Geist.color(.pink900, scheme: scheme)
        case .amber: Geist.color(.gray1000, scheme: scheme)
        }
    }

    private func borderColor(scheme: ColorScheme) -> Color {
        switch self {
        case .monochrome: Geist.color(.grayAlpha400, scheme: scheme)
        case .blue: Geist.color(.blue400, scheme: scheme)
        case .green: Geist.color(.green400, scheme: scheme)
        case .purple: Geist.color(.purple400, scheme: scheme)
        case .pink: Geist.color(.pink400, scheme: scheme)
        case .amber: Geist.color(.grayAlpha400, scheme: scheme)
        }
    }
}

public enum GamepadProfileOutputMode: String, Codable, CaseIterable, Identifiable, Sendable {
    case keyboard
    case controller
    case custom

    public var id: String { rawValue }

    var displayName: String {
        switch self {
        case .keyboard: "Keyboard"
        case .controller: "Controller"
        case .custom: "Custom"
        }
    }

    var description: String {
        switch self {
        case .keyboard:
            "Send this keypad as Mac keyboard shortcuts. Virtual controller output stays off for this setup."
        case .controller:
            "Send this keypad as a virtual Xbox-style controller using Thumble’s default controller map."
        case .custom:
            "Use per-element output bindings. This can mix keyboard shortcuts and virtual controller buttons."
        }
    }
}

private extension String {
    var nilIfBlank: String? {
        let trimmed = trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }
}

public struct GamepadProfileLaunchTarget: Codable, Equatable, Sendable {
    public enum TargetKind: String, Codable, Sendable {
        case application
    }

    public var kind: TargetKind
    public var displayName: String
    public static let maximumIconBytes = 200_000

    public var bundleIdentifier: String?
    public var filePath: String?
    public var bookmarkData: Data?
    public var iconPNGData: Data?
    public var attachedAt: Int64

    public init(
        kind: TargetKind = .application,
        displayName: String,
        bundleIdentifier: String? = nil,
        filePath: String? = nil,
        bookmarkData: Data? = nil,
        iconPNGData: Data? = nil,
        attachedAt: Int64 = Date.currentMilliseconds
    ) {
        self.kind = kind
        self.displayName = displayName
        self.bundleIdentifier = bundleIdentifier
        self.filePath = filePath
        self.bookmarkData = bookmarkData
        self.iconPNGData = iconPNGData
        self.attachedAt = attachedAt
    }

    public var normalized: GamepadProfileLaunchTarget {
        var copy = self
        let trimmedDisplayName = displayName.trimmingCharacters(in: .whitespacesAndNewlines)
        copy.displayName = trimmedDisplayName.isEmpty ? "Application" : trimmedDisplayName
        copy.bundleIdentifier = bundleIdentifier?.trimmingCharacters(in: .whitespacesAndNewlines).nilIfBlank
        copy.filePath = filePath?.trimmingCharacters(in: .whitespacesAndNewlines).nilIfBlank
        if let iconPNGData, iconPNGData.count <= Self.maximumIconBytes {
            copy.iconPNGData = iconPNGData
        } else {
            copy.iconPNGData = nil
        }
#if os(macOS)
        if copy.iconPNGData == nil, let applicationURL = copy.resolvedApplicationURL() {
            copy.iconPNGData = Self.applicationIconPNGData(for: applicationURL)
        }
#endif
        return copy
    }

    var detailText: String {
        if let bundleIdentifier = bundleIdentifier?.nilIfBlank {
            return bundleIdentifier
        }
        if let filePath = filePath?.nilIfBlank {
            return (filePath as NSString).abbreviatingWithTildeInPath
        }
        return "Mac application"
    }
}

#if os(macOS)
extension GamepadProfileLaunchTarget {
    static func application(url: URL, bookmarkData: Data? = nil) -> GamepadProfileLaunchTarget {
        let standardizedURL = url.standardizedFileURL
        let bundle = Bundle(url: standardizedURL)
        let bundleDisplayName = bundle?.object(forInfoDictionaryKey: "CFBundleDisplayName") as? String
        let bundleName = bundle?.object(forInfoDictionaryKey: "CFBundleName") as? String
        let displayName = bundleDisplayName?.nilIfBlank
            ?? bundleName?.nilIfBlank
            ?? standardizedURL.deletingPathExtension().lastPathComponent

        return GamepadProfileLaunchTarget(
            kind: .application,
            displayName: displayName,
            bundleIdentifier: bundle?.bundleIdentifier?.nilIfBlank,
            filePath: standardizedURL.path,
            bookmarkData: bookmarkData,
            iconPNGData: applicationIconPNGData(for: standardizedURL)
        ).normalized
    }

    static func applicationIconPNGData(for url: URL) -> Data? {
        let pixelSize = 128
        let image = NSWorkspace.shared.icon(forFile: url.path)
        let targetSize = NSSize(width: pixelSize, height: pixelSize)
        guard let representation = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: pixelSize,
            pixelsHigh: pixelSize,
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        ) else {
            return nil
        }
        representation.size = targetSize

        NSGraphicsContext.saveGraphicsState()
        guard let context = NSGraphicsContext(bitmapImageRep: representation) else {
            NSGraphicsContext.restoreGraphicsState()
            return nil
        }
        NSGraphicsContext.current = context
        context.imageInterpolation = .high
        image.draw(
            in: NSRect(origin: .zero, size: targetSize),
            from: NSRect(origin: .zero, size: image.size == .zero ? targetSize : image.size),
            operation: .copy,
            fraction: 1
        )
        NSGraphicsContext.restoreGraphicsState()

        guard let data = representation.representation(using: .png, properties: [:]),
              data.count <= maximumIconBytes
        else {
            return nil
        }
        return data
    }

    func resolvedApplicationURL() -> URL? {
        if let bookmarkData {
            var isStale = false
            if let bookmarkedURL = try? URL(
                resolvingBookmarkData: bookmarkData,
                options: [.withSecurityScope],
                relativeTo: nil,
                bookmarkDataIsStale: &isStale
            ) {
                return bookmarkedURL
            }
        }

        if let filePath = filePath?.nilIfBlank {
            let fileURL = URL(fileURLWithPath: (filePath as NSString).expandingTildeInPath)
            if FileManager.default.fileExists(atPath: fileURL.path) {
                return fileURL
            }
        }

        if let bundleIdentifier = bundleIdentifier?.nilIfBlank {
            return NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier)
        }

        return nil
    }
}
#endif

public enum GamepadProfileOrientationPreference: String, Codable, CaseIterable, Identifiable, Sendable {
    case automatic
    case portrait
    case landscape

    public var id: String { rawValue }

    public var displayName: String {
        switch self {
        case .automatic: "Follow Device"
        case .portrait: "Lock Portrait"
        case .landscape: "Lock Landscape"
        }
    }

    public var description: String {
        switch self {
        case .automatic: "Allow the iPhone to follow its physical orientation."
        case .portrait: "Keep the iPhone keypad in portrait orientation."
        case .landscape: "Keep the iPhone keypad in landscape orientation."
        }
    }
}

/// Immutable indirection keeps profile copies small while preserving struct value semantics.
/// Mutating a computed customization property replaces its box rather than sharing mutable state.
private final class GamepadProfileCustomizationBox: @unchecked Sendable {
    let value: GamepadCustomization

    init(_ value: GamepadCustomization) {
        self.value = value
    }
}

public struct GamepadConfigurationProfile: Identifiable, Codable, Equatable, Sendable {
    public var id: UUID
    public var name: String
    private var storedCustomization: GamepadProfileCustomizationBox
    private var storedLandscapeCustomization: GamepadProfileCustomizationBox?
    private var storedPortraitCustomization: GamepadProfileCustomizationBox?
    private var storedSkinBaselineCustomization: GamepadProfileCustomizationBox?
    private var storedLandscapeSkinBaselineCustomization: GamepadProfileCustomizationBox?
    private var storedPortraitSkinBaselineCustomization: GamepadProfileCustomizationBox?
    /// Installed appearance package. Geometry and executable bindings remain in this profile.
    public var skinReference: ThumbleSkinReference?
    public var orientationPreference: GamepadProfileOrientationPreference
    public var outputMode: GamepadProfileOutputMode
    public var launchTarget: GamepadProfileLaunchTarget?
    public var updatedAt: Int64

    /// Legacy/current layout. This remains the fallback for older saved profiles and
    /// clients, while orientation-specific variants below can override it on iPhone.
    public var customization: GamepadCustomization {
        get { storedCustomization.value }
        set { storedCustomization = GamepadProfileCustomizationBox(newValue) }
    }

    public var landscapeCustomization: GamepadCustomization? {
        get { storedLandscapeCustomization?.value }
        set { storedLandscapeCustomization = newValue.map(GamepadProfileCustomizationBox.init) }
    }

    public var portraitCustomization: GamepadCustomization? {
        get { storedPortraitCustomization?.value }
        set { storedPortraitCustomization = newValue.map(GamepadProfileCustomizationBox.init) }
    }

    /// Rendered baselines captured when the skin was applied. Differences between the current
    /// customization and these baselines are user overrides layered over future skin updates.
    public var skinBaselineCustomization: GamepadCustomization? {
        get { storedSkinBaselineCustomization?.value }
        set { storedSkinBaselineCustomization = newValue.map(GamepadProfileCustomizationBox.init) }
    }

    public var landscapeSkinBaselineCustomization: GamepadCustomization? {
        get { storedLandscapeSkinBaselineCustomization?.value }
        set { storedLandscapeSkinBaselineCustomization = newValue.map(GamepadProfileCustomizationBox.init) }
    }

    public var portraitSkinBaselineCustomization: GamepadCustomization? {
        get { storedPortraitSkinBaselineCustomization?.value }
        set { storedPortraitSkinBaselineCustomization = newValue.map(GamepadProfileCustomizationBox.init) }
    }

    public init(
        id: UUID = UUID(),
        name: String,
        customization: GamepadCustomization,
        landscapeCustomization: GamepadCustomization? = nil,
        portraitCustomization: GamepadCustomization? = nil,
        skinReference: ThumbleSkinReference? = nil,
        skinBaselineCustomization: GamepadCustomization? = nil,
        landscapeSkinBaselineCustomization: GamepadCustomization? = nil,
        portraitSkinBaselineCustomization: GamepadCustomization? = nil,
        orientationPreference: GamepadProfileOrientationPreference = .automatic,
        outputMode: GamepadProfileOutputMode = .keyboard,
        launchTarget: GamepadProfileLaunchTarget? = nil,
        updatedAt: Int64 = Date.currentMilliseconds
    ) {
        self.id = id
        self.name = name
        storedCustomization = GamepadProfileCustomizationBox(customization)
        storedLandscapeCustomization = landscapeCustomization.map(GamepadProfileCustomizationBox.init)
        storedPortraitCustomization = portraitCustomization.map(GamepadProfileCustomizationBox.init)
        storedSkinBaselineCustomization = skinBaselineCustomization.map(GamepadProfileCustomizationBox.init)
        storedLandscapeSkinBaselineCustomization = landscapeSkinBaselineCustomization.map(GamepadProfileCustomizationBox.init)
        storedPortraitSkinBaselineCustomization = portraitSkinBaselineCustomization.map(GamepadProfileCustomizationBox.init)
        self.skinReference = skinReference
        self.orientationPreference = orientationPreference
        self.outputMode = outputMode
        self.launchTarget = launchTarget
        self.updatedAt = updatedAt
        normalizeIdentityInPlace()
        normalizePrimaryCustomizationInPlace()
        normalizeLandscapeCustomizationInPlace()
        normalizePortraitCustomizationInPlace()
        normalizeSkinBaselineCustomizationInPlace()
        normalizeLandscapeSkinBaselineCustomizationInPlace()
        normalizePortraitSkinBaselineCustomizationInPlace()
        normalizeLaunchTargetInPlace()
    }

    /// Stack-safe construction for profiles that begin with only a primary layout.
    /// The full public initializer remains available for imports that already carry
    /// orientation variants and skin baselines.
    init(
        id: UUID = UUID(),
        name: String,
        primaryCustomization: GamepadCustomization,
        skinReference: ThumbleSkinReference? = nil,
        orientationPreference: GamepadProfileOrientationPreference = .automatic,
        outputMode: GamepadProfileOutputMode = .keyboard,
        launchTarget: GamepadProfileLaunchTarget? = nil,
        updatedAt: Int64 = Date.currentMilliseconds
    ) {
        self.id = id
        self.name = name
        storedCustomization = GamepadProfileCustomizationBox(primaryCustomization)
        storedLandscapeCustomization = nil
        storedPortraitCustomization = nil
        storedSkinBaselineCustomization = nil
        storedLandscapeSkinBaselineCustomization = nil
        storedPortraitSkinBaselineCustomization = nil
        self.skinReference = skinReference
        self.orientationPreference = orientationPreference
        self.outputMode = outputMode
        self.launchTarget = launchTarget
        self.updatedAt = updatedAt
        normalizeIdentityInPlace()
        normalizePrimaryCustomizationInPlace()
        normalizeLaunchTargetInPlace()
    }

    public init(from decoder: Decoder) throws {
        let workspace = DecodingWorkspace()
        let container = try decoder.container(keyedBy: CodingKeys.self)
        try Self.decodeIdentityFields(from: container, into: workspace)
        try Self.decodePrimaryCustomization(from: container, into: workspace)
        try Self.decodeLandscapeCustomization(from: container, into: workspace)
        try Self.decodePortraitCustomization(from: container, into: workspace)
        try Self.decodeSkinBaselineCustomization(from: container, into: workspace)
        try Self.decodeLandscapeSkinBaselineCustomization(from: container, into: workspace)
        try Self.decodePortraitSkinBaselineCustomization(from: container, into: workspace)
        try Self.decodeProfileMetadata(from: container, into: workspace)
        self.init(decoded: workspace)
    }

    private final class DecodingWorkspace {
        var id = UUID()
        var name = "Untitled"
        var customization = GamepadCustomization.defaultValue
        var landscapeCustomization: GamepadCustomization?
        var portraitCustomization: GamepadCustomization?
        var skinReference: ThumbleSkinReference?
        var skinBaselineCustomization: GamepadCustomization?
        var landscapeSkinBaselineCustomization: GamepadCustomization?
        var portraitSkinBaselineCustomization: GamepadCustomization?
        var orientationPreference = GamepadProfileOrientationPreference.automatic
        var outputMode = GamepadProfileOutputMode.custom
        var launchTarget: GamepadProfileLaunchTarget?
        var updatedAt = Date.currentMilliseconds
    }

    private init(decoded workspace: DecodingWorkspace) {
        id = workspace.id
        name = workspace.name
        storedCustomization = GamepadProfileCustomizationBox(.defaultValue)
        storedLandscapeCustomization = nil
        storedPortraitCustomization = nil
        storedSkinBaselineCustomization = nil
        storedLandscapeSkinBaselineCustomization = nil
        storedPortraitSkinBaselineCustomization = nil
        skinReference = workspace.skinReference
        orientationPreference = workspace.orientationPreference
        outputMode = workspace.outputMode
        launchTarget = workspace.launchTarget
        updatedAt = workspace.updatedAt
        Self.commitPrimaryCustomization(from: workspace, into: &self)
        Self.commitLandscapeCustomization(from: workspace, into: &self)
        Self.commitPortraitCustomization(from: workspace, into: &self)
        Self.commitSkinBaselineCustomization(from: workspace, into: &self)
        Self.commitLandscapeSkinBaselineCustomization(from: workspace, into: &self)
        Self.commitPortraitSkinBaselineCustomization(from: workspace, into: &self)
    }

    private static func commitPrimaryCustomization(
        from workspace: DecodingWorkspace,
        into profile: inout GamepadConfigurationProfile
    ) {
        profile.storedCustomization = GamepadProfileCustomizationBox(workspace.customization)
    }

    private static func commitLandscapeCustomization(
        from workspace: DecodingWorkspace,
        into profile: inout GamepadConfigurationProfile
    ) {
        profile.storedLandscapeCustomization = workspace.landscapeCustomization.map(GamepadProfileCustomizationBox.init)
    }

    private static func commitPortraitCustomization(
        from workspace: DecodingWorkspace,
        into profile: inout GamepadConfigurationProfile
    ) {
        profile.storedPortraitCustomization = workspace.portraitCustomization.map(GamepadProfileCustomizationBox.init)
    }

    private static func commitSkinBaselineCustomization(
        from workspace: DecodingWorkspace,
        into profile: inout GamepadConfigurationProfile
    ) {
        profile.storedSkinBaselineCustomization = workspace.skinBaselineCustomization.map(GamepadProfileCustomizationBox.init)
    }

    private static func commitLandscapeSkinBaselineCustomization(
        from workspace: DecodingWorkspace,
        into profile: inout GamepadConfigurationProfile
    ) {
        profile.storedLandscapeSkinBaselineCustomization = workspace.landscapeSkinBaselineCustomization.map(GamepadProfileCustomizationBox.init)
    }

    private static func commitPortraitSkinBaselineCustomization(
        from workspace: DecodingWorkspace,
        into profile: inout GamepadConfigurationProfile
    ) {
        profile.storedPortraitSkinBaselineCustomization = workspace.portraitSkinBaselineCustomization.map(GamepadProfileCustomizationBox.init)
    }

    private static func decodeIdentityFields(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        workspace.id = try container.decodeIfPresent(UUID.self, forKey: .id) ?? UUID()
        workspace.name = try container.decodeIfPresent(String.self, forKey: .name) ?? "Untitled"
    }

    private static func decodePrimaryCustomization(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        let decoded = try container.decodeIfPresent(GamepadCustomization.self, forKey: .customization) ?? .defaultValue
        workspace.customization = decoded.normalized
    }

    private static func decodeLandscapeCustomization(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        guard let decoded = try container.decodeIfPresent(GamepadCustomization.self, forKey: .landscapeCustomization) else { return }
        workspace.landscapeCustomization = decoded.normalized
    }

    private static func decodePortraitCustomization(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        guard let decoded = try container.decodeIfPresent(GamepadCustomization.self, forKey: .portraitCustomization) else { return }
        workspace.portraitCustomization = decoded.normalized
    }

    private static func decodeSkinBaselineCustomization(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        guard let decoded = try container.decodeIfPresent(GamepadCustomization.self, forKey: .skinBaselineCustomization) else { return }
        workspace.skinBaselineCustomization = decoded.normalized
    }

    private static func decodeLandscapeSkinBaselineCustomization(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        guard let decoded = try container.decodeIfPresent(GamepadCustomization.self, forKey: .landscapeSkinBaselineCustomization) else { return }
        workspace.landscapeSkinBaselineCustomization = decoded.normalized
    }

    private static func decodePortraitSkinBaselineCustomization(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        guard let decoded = try container.decodeIfPresent(GamepadCustomization.self, forKey: .portraitSkinBaselineCustomization) else { return }
        workspace.portraitSkinBaselineCustomization = decoded.normalized
    }

    private static func decodeProfileMetadata(
        from container: KeyedDecodingContainer<CodingKeys>,
        into workspace: DecodingWorkspace
    ) throws {
        workspace.skinReference = try container.decodeIfPresent(ThumbleSkinReference.self, forKey: .skinReference)
        workspace.orientationPreference = try container.decodeIfPresent(GamepadProfileOrientationPreference.self, forKey: .orientationPreference) ?? .automatic
        // Profiles saved before output modes had their Mac output bindings stored next
        // to the profile, not inside it. Treat legacy profiles as custom so any
        // existing mixed keyboard/controller bindings keep working after migration.
        workspace.outputMode = try container.decodeIfPresent(GamepadProfileOutputMode.self, forKey: .outputMode) ?? .custom
        workspace.launchTarget = try container.decodeIfPresent(GamepadProfileLaunchTarget.self, forKey: .launchTarget)?.normalized
        workspace.updatedAt = try container.decodeIfPresent(Int64.self, forKey: .updatedAt) ?? Date.currentMilliseconds
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try encodeIdentityFields(into: &container)
        try encodePrimaryCustomization(into: &container)
        try encodeLandscapeCustomization(into: &container)
        try encodePortraitCustomization(into: &container)
        try encodeSkinBaselineCustomization(into: &container)
        try encodeLandscapeSkinBaselineCustomization(into: &container)
        try encodePortraitSkinBaselineCustomization(into: &container)
        try encodeProfileMetadata(into: &container)
    }

    private func encodeIdentityFields(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        try container.encode(id, forKey: .id)
        try container.encode(name, forKey: .name)
    }

    private func encodePrimaryCustomization(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        try container.encode(storedCustomization.value, forKey: .customization)
    }

    private func encodeLandscapeCustomization(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        guard let box = storedLandscapeCustomization else { return }
        try container.encode(box.value, forKey: .landscapeCustomization)
    }

    private func encodePortraitCustomization(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        guard let box = storedPortraitCustomization else { return }
        try container.encode(box.value, forKey: .portraitCustomization)
    }

    private func encodeSkinBaselineCustomization(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        guard let box = storedSkinBaselineCustomization else { return }
        try container.encode(box.value, forKey: .skinBaselineCustomization)
    }

    private func encodeLandscapeSkinBaselineCustomization(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        guard let box = storedLandscapeSkinBaselineCustomization else { return }
        try container.encode(box.value, forKey: .landscapeSkinBaselineCustomization)
    }

    private func encodePortraitSkinBaselineCustomization(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        guard let box = storedPortraitSkinBaselineCustomization else { return }
        try container.encode(box.value, forKey: .portraitSkinBaselineCustomization)
    }

    private func encodeProfileMetadata(
        into container: inout KeyedEncodingContainer<CodingKeys>
    ) throws {
        try container.encodeIfPresent(skinReference, forKey: .skinReference)
        try container.encode(orientationPreference, forKey: .orientationPreference)
        try container.encode(outputMode, forKey: .outputMode)
        try container.encodeIfPresent(launchTarget?.normalized, forKey: .launchTarget)
        try container.encode(updatedAt, forKey: .updatedAt)
    }

    public static func == (
        lhs: GamepadConfigurationProfile,
        rhs: GamepadConfigurationProfile
    ) -> Bool {
        EqualityWorkspace(lhs, rhs).matches
    }

    private final class EqualityWorkspace {
        private let lhs: GamepadConfigurationProfile
        private let rhs: GamepadConfigurationProfile

        init(_ lhs: GamepadConfigurationProfile, _ rhs: GamepadConfigurationProfile) {
            self.lhs = lhs
            self.rhs = rhs
        }

        var matches: Bool {
            if !matchesIdentityAndMetadata { return false }
            if !matchesPrimaryCustomization { return false }
            if !matchesLandscapeCustomization { return false }
            if !matchesPortraitCustomization { return false }
            if !matchesSkinBaselineCustomization { return false }
            if !matchesLandscapeSkinBaselineCustomization { return false }
            return matchesPortraitSkinBaselineCustomization
        }

        private var matchesIdentityAndMetadata: Bool {
            if lhs.id != rhs.id { return false }
            if lhs.name != rhs.name { return false }
            if lhs.skinReference != rhs.skinReference { return false }
            if lhs.orientationPreference != rhs.orientationPreference { return false }
            if lhs.outputMode != rhs.outputMode { return false }
            if lhs.launchTarget != rhs.launchTarget { return false }
            return lhs.updatedAt == rhs.updatedAt
        }

        private var matchesPrimaryCustomization: Bool {
            lhs.storedCustomization.value == rhs.storedCustomization.value
        }

        private var matchesLandscapeCustomization: Bool {
            Self.matches(lhs.storedLandscapeCustomization, rhs.storedLandscapeCustomization)
        }

        private var matchesPortraitCustomization: Bool {
            Self.matches(lhs.storedPortraitCustomization, rhs.storedPortraitCustomization)
        }

        private var matchesSkinBaselineCustomization: Bool {
            Self.matches(lhs.storedSkinBaselineCustomization, rhs.storedSkinBaselineCustomization)
        }

        private var matchesLandscapeSkinBaselineCustomization: Bool {
            Self.matches(
                lhs.storedLandscapeSkinBaselineCustomization,
                rhs.storedLandscapeSkinBaselineCustomization
            )
        }

        private var matchesPortraitSkinBaselineCustomization: Bool {
            Self.matches(
                lhs.storedPortraitSkinBaselineCustomization,
                rhs.storedPortraitSkinBaselineCustomization
            )
        }

        private static func matches(
            _ lhs: GamepadProfileCustomizationBox?,
            _ rhs: GamepadProfileCustomizationBox?
        ) -> Bool {
            switch (lhs, rhs) {
            case (nil, nil):
                return true
            case let (lhs?, rhs?):
                return lhs.value == rhs.value
            default:
                return false
            }
        }
    }

    public var normalized: GamepadConfigurationProfile {
        var copy = self
        copy.normalizeIdentityInPlace()
        copy.normalizePrimaryCustomizationInPlace()
        copy.normalizeLandscapeCustomizationInPlace()
        copy.normalizePortraitCustomizationInPlace()
        copy.normalizeSkinBaselineCustomizationInPlace()
        copy.normalizeLandscapeSkinBaselineCustomizationInPlace()
        copy.normalizePortraitSkinBaselineCustomizationInPlace()
        copy.normalizeLaunchTargetInPlace()
        return copy
    }

    private mutating func normalizeIdentityInPlace() {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        name = trimmedName.isEmpty ? "Untitled" : trimmedName
    }

    private mutating func normalizePrimaryCustomizationInPlace() {
        storedCustomization = GamepadProfileCustomizationBox(storedCustomization.value.normalized)
    }

    private mutating func normalizeLandscapeCustomizationInPlace() {
        guard let box = storedLandscapeCustomization else { return }
        storedLandscapeCustomization = GamepadProfileCustomizationBox(box.value.normalized)
    }

    private mutating func normalizePortraitCustomizationInPlace() {
        guard let box = storedPortraitCustomization else { return }
        storedPortraitCustomization = GamepadProfileCustomizationBox(box.value.normalized)
    }

    private mutating func normalizeSkinBaselineCustomizationInPlace() {
        guard let box = storedSkinBaselineCustomization else { return }
        storedSkinBaselineCustomization = GamepadProfileCustomizationBox(box.value.normalized)
    }

    private mutating func normalizeLandscapeSkinBaselineCustomizationInPlace() {
        guard let box = storedLandscapeSkinBaselineCustomization else { return }
        storedLandscapeSkinBaselineCustomization = GamepadProfileCustomizationBox(box.value.normalized)
    }

    private mutating func normalizePortraitSkinBaselineCustomizationInPlace() {
        guard let box = storedPortraitSkinBaselineCustomization else { return }
        storedPortraitSkinBaselineCustomization = GamepadProfileCustomizationBox(box.value.normalized)
    }

    private mutating func normalizeLaunchTargetInPlace() {
        launchTarget = launchTarget?.normalized
    }

    private final class CustomizationResolutionWorkspace {
        private var resolvedBox: GamepadProfileCustomizationBox
        private let primaryColorSchemePreference: GamepadColorSchemePreference

        init(
            selectedBox: GamepadProfileCustomizationBox,
            primaryColorSchemePreference: GamepadColorSchemePreference
        ) {
            resolvedBox = selectedBox
            self.primaryColorSchemePreference = primaryColorSchemePreference
        }

        func resolve() -> GamepadCustomization {
            normalizeSelectedCustomization()
            applyPrimaryColorSchemePreference()
            return resolvedBox.value
        }

        private func normalizeSelectedCustomization() {
            resolvedBox = GamepadProfileCustomizationBox(resolvedBox.value.normalized)
        }

        private func applyPrimaryColorSchemePreference() {
            var resolved = resolvedBox.value
            // Saved Mode is a setup-level preference, not a per-orientation design choice.
            resolved.colorSchemePreference = primaryColorSchemePreference
            resolvedBox = GamepadProfileCustomizationBox(resolved)
        }
    }

    func customization(for orientation: GamepadEditorDeviceOrientation) -> GamepadCustomization {
        let selectedBox: GamepadProfileCustomizationBox
        switch orientation {
        case .landscape:
            selectedBox = storedLandscapeCustomization ?? storedCustomization
        case .portrait:
            selectedBox = storedPortraitCustomization ?? storedCustomization
        }
        return CustomizationResolutionWorkspace(
            selectedBox: selectedBox,
            primaryColorSchemePreference: storedCustomization.value.colorSchemePreference
        ).resolve()
    }

    func skinBaseline(for orientation: GamepadEditorDeviceOrientation) -> GamepadCustomization? {
        let selectedBox: GamepadProfileCustomizationBox?
        switch orientation {
        case .landscape:
            selectedBox = storedLandscapeSkinBaselineCustomization ?? storedSkinBaselineCustomization
        case .portrait:
            selectedBox = storedPortraitSkinBaselineCustomization ?? storedSkinBaselineCustomization
        }
        return selectedBox?.value.normalized
    }

    func resolvedCustomization(
        for orientation: GamepadEditorDeviceOrientation,
        colorScheme: ThumbleSkinColorScheme,
        skinPackage: ThumbleSkinPackage?
    ) -> GamepadCustomization {
        let local = customization(for: orientation)
        guard let skinReference,
              let skinPackage,
              skinPackage.manifest.identifier == skinReference.identifier,
              skinPackage.manifest.version == skinReference.version
        else { return local }
        return local.applying(
            skinPackage: skinPackage,
            orientation: orientation == .portrait ? .portrait : .landscape,
            colorScheme: colorScheme,
            options: .preservingUserOverrides,
            overrideBaseline: skinBaseline(for: orientation)
        )
    }

    mutating func applySkin(
        _ package: ThumbleSkinPackage,
        colorScheme: ThumbleSkinColorScheme = .light
    ) {
        let workspace = SkinApplicationWorkspace(
            profile: self,
            package: package,
            colorScheme: colorScheme
        )
        workspace.apply()
        self = workspace.profile
    }

    private final class SkinApplicationWorkspace {
        private(set) var profile: GamepadConfigurationProfile
        private let package: ThumbleSkinPackage
        private let colorScheme: ThumbleSkinColorScheme
        private let previousFallbackBaseline: GamepadCustomization?
        private var preparedSlot: SkinSlotApplicationWorkspace?

        init(
            profile: GamepadConfigurationProfile,
            package: ThumbleSkinPackage,
            colorScheme: ThumbleSkinColorScheme
        ) {
            self.profile = profile
            self.package = package
            self.colorScheme = colorScheme
            self.previousFallbackBaseline = profile.storedSkinBaselineCustomization?.value
        }

        func apply() {
            applyFallback()
            applyLandscapeIfPresent()
            applyPortraitIfPresent()
            profile.skinReference = ThumbleSkinReference(
                identifier: package.manifest.identifier,
                version: package.manifest.version
            )
            profile.updatedAt = Date.currentMilliseconds
        }

        private func applyFallback() {
            prepareFallbackSlot()
            resolvePreparedSlot()
            commitFallbackSlot()
            preparedSlot = nil
        }

        private func prepareFallbackSlot() {
            let source = profile.storedCustomization.value
            let fallbackOrientation = source.deviceCanvas.editorDeviceFrame.orientation
            let skinOrientation: ThumbleSkinOrientation = fallbackOrientation == .portrait ? .portrait : .landscape
            preparedSlot = SkinSlotApplicationWorkspace(
                source: source,
                previousBaseline: previousFallbackBaseline,
                package: package,
                orientation: skinOrientation,
                colorScheme: colorScheme
            )
        }

        private func commitFallbackSlot() {
            guard let preparedSlot else { return }
            profile.storedCustomization = GamepadProfileCustomizationBox(preparedSlot.result)
            profile.storedSkinBaselineCustomization = GamepadProfileCustomizationBox(preparedSlot.baseline)
        }

        private func applyLandscapeIfPresent() {
            preparedSlot = nil
            prepareLandscapeSlot()
            guard preparedSlot != nil else { return }
            resolvePreparedSlot()
            commitLandscapeSlot()
            preparedSlot = nil
        }

        private func prepareLandscapeSlot() {
            guard let sourceBox = profile.storedLandscapeCustomization else { return }
            let previousBaseline = profile.storedLandscapeSkinBaselineCustomization?.value
                ?? previousFallbackBaseline
            preparedSlot = SkinSlotApplicationWorkspace(
                source: sourceBox.value,
                previousBaseline: previousBaseline,
                package: package,
                orientation: .landscape,
                colorScheme: colorScheme
            )
        }

        private func commitLandscapeSlot() {
            guard let preparedSlot else { return }
            profile.storedLandscapeCustomization = GamepadProfileCustomizationBox(preparedSlot.result)
            profile.storedLandscapeSkinBaselineCustomization = GamepadProfileCustomizationBox(preparedSlot.baseline)
        }

        private func applyPortraitIfPresent() {
            preparedSlot = nil
            preparePortraitSlot()
            guard preparedSlot != nil else { return }
            resolvePreparedSlot()
            commitPortraitSlot()
            preparedSlot = nil
        }

        private func preparePortraitSlot() {
            guard let sourceBox = profile.storedPortraitCustomization else { return }
            let previousBaseline = profile.storedPortraitSkinBaselineCustomization?.value
                ?? previousFallbackBaseline
            preparedSlot = SkinSlotApplicationWorkspace(
                source: sourceBox.value,
                previousBaseline: previousBaseline,
                package: package,
                orientation: .portrait,
                colorScheme: colorScheme
            )
        }

        private func commitPortraitSlot() {
            guard let preparedSlot else { return }
            profile.storedPortraitCustomization = GamepadProfileCustomizationBox(preparedSlot.result)
            profile.storedPortraitSkinBaselineCustomization = GamepadProfileCustomizationBox(preparedSlot.baseline)
        }

        private func resolvePreparedSlot() {
            preparedSlot?.resolve()
        }
    }

    private final class SkinSlotApplicationWorkspace {
        private let source: GamepadCustomization
        private let previousBaseline: GamepadCustomization?
        private let package: ThumbleSkinPackage
        private let orientation: ThumbleSkinOrientation
        private let colorScheme: ThumbleSkinColorScheme
        private(set) var baseline: GamepadCustomization
        private(set) var result: GamepadCustomization

        init(
            source: GamepadCustomization,
            previousBaseline: GamepadCustomization?,
            package: ThumbleSkinPackage,
            orientation: ThumbleSkinOrientation,
            colorScheme: ThumbleSkinColorScheme
        ) {
            self.source = source
            self.previousBaseline = previousBaseline
            self.package = package
            self.orientation = orientation
            self.colorScheme = colorScheme
            self.baseline = source
            self.result = source
        }

        func resolve() {
            resolveBaseline()
            resolveResult()
        }

        private func resolveBaseline() {
            baseline = source.applying(
                skinPackage: package,
                orientation: orientation,
                colorScheme: colorScheme,
                options: .replacingAppearance
            )
            baseline.dehydrateAssetReferencesInPlace(from: package)
        }

        private func resolveResult() {
            guard let previousBaseline else {
                result = baseline
                return
            }
            result = source.applying(
                skinPackage: package,
                orientation: orientation,
                colorScheme: colorScheme,
                options: .preservingUserOverrides,
                overrideBaseline: previousBaseline
            )
            result.dehydrateAssetReferencesInPlace(from: package)
        }
    }

    /// Materializes the selected variant and package assets before removing the package dependency.
    mutating func detachSkin(
        resolving package: ThumbleSkinPackage,
        colorScheme: ThumbleSkinColorScheme
    ) {
        let workspace = SkinDetachmentWorkspace(
            profile: self,
            package: package,
            colorScheme: colorScheme
        )
        workspace.resolve()
        self = workspace.profile
    }

    private final class SkinDetachmentWorkspace {
        private(set) var profile: GamepadConfigurationProfile
        private let package: ThumbleSkinPackage
        private let colorScheme: ThumbleSkinColorScheme
        private var fallbackBox: GamepadProfileCustomizationBox?
        private var landscapeBox: GamepadProfileCustomizationBox?
        private var portraitBox: GamepadProfileCustomizationBox?

        init(
            profile: GamepadConfigurationProfile,
            package: ThumbleSkinPackage,
            colorScheme: ThumbleSkinColorScheme
        ) {
            self.profile = profile
            self.package = package
            self.colorScheme = colorScheme
        }

        func resolve() {
            resolveFallback()
            resolveLandscapeIfPresent()
            resolvePortraitIfPresent()
            commitResolvedCustomizations()
        }

        private func resolveFallback() {
            let orientation = profile.storedCustomization.value
                .deviceCanvas.editorDeviceFrame.orientation
            fallbackBox = GamepadProfileCustomizationBox(
                profile.resolvedCustomization(
                    for: orientation,
                    colorScheme: colorScheme,
                    skinPackage: package
                )
            )
        }

        private func resolveLandscapeIfPresent() {
            guard profile.storedLandscapeCustomization != nil else { return }
            landscapeBox = GamepadProfileCustomizationBox(
                profile.resolvedCustomization(
                    for: .landscape,
                    colorScheme: colorScheme,
                    skinPackage: package
                )
            )
        }

        private func resolvePortraitIfPresent() {
            guard profile.storedPortraitCustomization != nil else { return }
            portraitBox = GamepadProfileCustomizationBox(
                profile.resolvedCustomization(
                    for: .portrait,
                    colorScheme: colorScheme,
                    skinPackage: package
                )
            )
        }

        private func commitResolvedCustomizations() {
            guard let fallbackBox else { return }
            profile.storedCustomization = fallbackBox
            profile.storedLandscapeCustomization = landscapeBox
            profile.storedPortraitCustomization = portraitBox
            profile.detachSkin()
        }
    }

    /// Keeps the saved appearance and makes it fully local/editable.
    mutating func detachSkin() {
        skinReference = nil
        storedSkinBaselineCustomization = nil
        storedLandscapeSkinBaselineCustomization = nil
        storedPortraitSkinBaselineCustomization = nil
        updatedAt = Date.currentMilliseconds
    }

    func hasCustomizationVariant(for orientation: GamepadEditorDeviceOrientation) -> Bool {
        switch orientation {
        case .landscape: storedLandscapeCustomization != nil
        case .portrait: storedPortraitCustomization != nil
        }
    }

    /// Adds or replaces one orientation slot without changing the primary layout.
    /// Keeping this operation separate avoids passing several large optional values
    /// through the full initializer at once.
    mutating func setCustomizationVariant(
        _ customization: GamepadCustomization,
        for orientation: GamepadEditorDeviceOrientation
    ) {
        let box = GamepadProfileCustomizationBox(customization.normalized)
        switch orientation {
        case .landscape:
            storedLandscapeCustomization = box
        case .portrait:
            storedPortraitCustomization = box
        }
    }

    mutating func setCustomization(
        _ customization: GamepadCustomization,
        for orientation: GamepadEditorDeviceOrientation
    ) {
        let workspace = CustomizationMutationWorkspace(
            profile: self,
            customization: customization,
            orientation: orientation
        )
        workspace.apply()
        self = workspace.profile
    }

    private final class CustomizationMutationWorkspace {
        private(set) var profile: GamepadConfigurationProfile
        private let customization: GamepadCustomization
        private let orientation: GamepadEditorDeviceOrientation
        private var preparedCustomization: GamepadCustomization?
        private var correctedOrientation = false
        private var replacementBox: GamepadProfileCustomizationBox?

        init(
            profile: GamepadConfigurationProfile,
            customization: GamepadCustomization,
            orientation: GamepadEditorDeviceOrientation
        ) {
            self.profile = profile
            self.customization = customization
            self.orientation = orientation
        }

        func apply() {
            preservePreviousOrientationIfNeeded()
            prepareReplacement()
            commitReplacement()
        }

        private func preservePreviousOrientationIfNeeded() {
            let previousCustomization = profile.storedCustomization.value.normalized
            let previousOrientation = previousCustomization.deviceCanvas.editorDeviceFrame.orientation
            guard previousOrientation != orientation,
                  !profile.hasCustomizationVariant(for: previousOrientation)
            else { return }

            let previousBox = GamepadProfileCustomizationBox(previousCustomization)
            switch previousOrientation {
            case .landscape:
                profile.storedLandscapeCustomization = previousBox
            case .portrait:
                profile.storedPortraitCustomization = previousBox
            }
        }

        private func prepareReplacement() {
            normalizeIncomingCustomization()
            correctPreparedOrientationIfNeeded()
            normalizeCorrectedOrientationIfNeeded()
            boxPreparedCustomization()
        }

        private func normalizeIncomingCustomization() {
            preparedCustomization = customization.normalized
        }

        private func correctPreparedOrientationIfNeeded() {
            guard var preparedCustomization else { return }
            let storedFrame = preparedCustomization.deviceCanvas.editorDeviceFrame
            guard storedFrame.orientation != orientation else { return }
            preparedCustomization.deviceCanvas = GamepadDeviceCanvas(
                frameID: GamepadEditorDeviceFrame(
                    spec: storedFrame.spec,
                    orientation: orientation
                ).id
            )
            self.preparedCustomization = preparedCustomization
            correctedOrientation = true
        }

        private func normalizeCorrectedOrientationIfNeeded() {
            guard correctedOrientation, let preparedCustomization else { return }
            self.preparedCustomization = preparedCustomization.normalized
        }

        private func boxPreparedCustomization() {
            guard let preparedCustomization else { return }
            replacementBox = GamepadProfileCustomizationBox(preparedCustomization)
        }

        private func commitReplacement() {
            guard let replacementBox else { return }
            profile.storedCustomization = replacementBox
            switch orientation {
            case .landscape:
                profile.storedLandscapeCustomization = replacementBox
            case .portrait:
                profile.storedPortraitCustomization = replacementBox
            }
        }
    }

    private enum CodingKeys: String, CodingKey {
        case id
        case name
        case customization
        case landscapeCustomization
        case portraitCustomization
        case skinReference
        case skinBaselineCustomization
        case landscapeSkinBaselineCustomization
        case portraitSkinBaselineCustomization
        case orientationPreference
        case outputMode
        case launchTarget
        case updatedAt
    }
}

enum GamepadControllerTemplate: String, CaseIterable, Identifiable {
    case productivityStarter
    case productivityOneHandedLeft
    case productivityOneHandedRight
    case nes
    case snes
    case nintendo64
    case gameCube
    case gameBoy
    case gameBoyAdvance
    case genesisSixButton
    case saturn
    case dreamcast
    case arcadeStick
    case psp
    case playStation
    case xbox
    case softWhite

    var id: String { rawValue }

    /// Increment when canonical geometry or semantics change incompatibly.
    var templateRevision: Int {
        switch self {
        case .snes: 2
        default: 1
        }
    }

    var displayName: String {
        switch self {
        case .productivityStarter: "Productivity Starter"
        case .productivityOneHandedLeft: "One-Handed Left"
        case .productivityOneHandedRight: "One-Handed Right"
        case .nes: "NES"
        case .snes: "Super Nintendo"
        case .nintendo64: "Nintendo 64"
        case .gameCube: "GameCube"
        case .gameBoy: "Game Boy"
        case .gameBoyAdvance: "Game Boy Advance"
        case .genesisSixButton: "Genesis 6-Button"
        case .saturn: "Sega Saturn"
        case .dreamcast: "Dreamcast"
        case .arcadeStick: "Arcade Stick"
        case .psp: "PSP"
        case .playStation: "PlayStation"
        case .xbox: "Xbox"
        case .softWhite: "Soft White Pro"
        }
    }

    var description: String {
        switch self {
        case .productivityStarter: "Everyday Mac navigation and shortcuts with tailored landscape and portrait layouts"
        case .productivityOneHandedLeft: "Everyday Mac controls grouped in the lower-left thumb zone"
        case .productivityOneHandedRight: "Everyday Mac controls grouped in the lower-right thumb zone"
        case .nes: "Classic console pad: D-pad, A/B, Select, Start"
        case .snes: "Super Nintendo pad: D-pad, ABXY, L/R shoulders, Select, Start"
        case .nintendo64: "Three-prong N64 layout with analog stick, Z trigger, and C-buttons"
        case .gameCube: "GameCube layout with oversized A, C-stick, shoulders, and Z"
        case .gameBoy: "Classic handheld: D-pad, A/B, Select, Start"
        case .gameBoyAdvance: "GBA handheld: D-pad, A/B, L/R shoulders, Select, Start"
        case .genesisSixButton: "Sega Genesis/Mega Drive pad with D-pad, A/B/C, X/Y/Z, Mode, Start"
        case .saturn: "Sega Saturn six-button layout with D-pad, L/R, and Start"
        case .dreamcast: "Dreamcast layout with analog stick, D-pad, ABXY, L/R triggers, Start"
        case .arcadeStick: "MAME/fight-stick layout with joystick, 8 buttons, Coin, and Start"
        case .psp: "Portable emulator pad with D-pad, nub, shoulders, and face buttons"
        case .playStation: "Dual-stick layout with PlayStation face symbols and shoulders"
        case .xbox: "Dual-stick Xbox-style layout with ABXY and triggers"
        case .softWhite: "Premium soft-white neumorphic controller with layered shell, rings, plates, dual sticks, D-pad, ABXY, and shoulder controls"
        }
    }

    var systemImage: String {
        switch self {
        case .productivityStarter: "keyboard"
        case .productivityOneHandedLeft: "hand.point.left.fill"
        case .productivityOneHandedRight: "hand.point.right.fill"
        case .nes, .snes: "gamecontroller"
        case .nintendo64: "circle.grid.cross"
        case .gameCube: "gamecontroller.fill"
        case .gameBoy, .gameBoyAdvance: "rectangle.roundedtop"
        case .genesisSixButton, .saturn: "dpad"
        case .dreamcast, .psp: "gamecontroller"
        case .arcadeStick: "circle.grid.3x3.fill"
        case .playStation: "gamecontroller.fill"
        case .xbox: "circle.grid.cross"
        case .softWhite: "sparkles"
        }
    }

    func makeProfile() -> GamepadConfigurationProfile {
        var profile = makeUntaggedProfile()
        tagPrimaryCustomization(in: &profile)
        tagLandscapeCustomization(in: &profile)
        tagPortraitCustomization(in: &profile)
        return profile
    }

    private func makeUntaggedProfile() -> GamepadConfigurationProfile {
        switch self {
        case .productivityStarter:
            return makeProductivityStarterProfile()
        case .productivityOneHandedLeft, .productivityOneHandedRight:
            return makeOneHandedProductivityProfile()
        case .nes:
            return makeNESProfile()
        case .snes:
            return makeSNESProfile()
        case .nintendo64:
            return makeNintendo64Profile()
        case .gameCube:
            return makeGameCubeProfile()
        case .gameBoy:
            return makeGameBoyProfile()
        case .gameBoyAdvance:
            return makeGameBoyAdvanceProfile()
        case .genesisSixButton:
            return makeGenesisProfile()
        case .saturn:
            return makeSaturnProfile()
        case .dreamcast:
            return makeDreamcastProfile()
        case .arcadeStick:
            return makeArcadeStickProfile()
        case .psp:
            return makePSPProfile()
        case .playStation:
            return makePlayStationProfile()
        case .xbox:
            return makeXboxProfile()
        case .softWhite:
            return makeSoftWhiteProfile()
        }
    }

    private func makePrimaryProfile(
        _ customization: GamepadCustomization
    ) -> GamepadConfigurationProfile {
        GamepadConfigurationProfile(
            name: displayName,
            primaryCustomization: customization
        )
    }

    private func makeNESProfile() -> GamepadConfigurationProfile {
        makePrimaryProfile(Self.nesCustomization())
    }

    private func makeSNESProfile() -> GamepadConfigurationProfile {
