    init(
        customization: Binding<GamepadCustomization>,
        showsPreview: Bool = true,
        initialProfiles: [GamepadConfigurationProfile]? = nil,
        initialSelectedProfileID: UUID? = nil,
        initialDefaultProfileID: UUID? = nil,
        onReset: (() -> Void)? = nil,
        onProfilesChanged: (([GamepadConfigurationProfile], UUID, UUID) -> Void)? = nil,
        onExportProfiles: (([GamepadConfigurationProfile], UUID, UUID, UUID?) -> Void)? = nil,
        onImportProfiles: ((Data, String, Bool) throws -> String)? = nil,
        onRegisterProfileUndoSnapshot: ((String) -> Void)? = nil,
        onLaunchProfileTarget: ((UUID) -> Void)? = nil,
        defaultLabelProvider: ((GameButton) -> String?)? = nil,
        profileOutputModeContent: (() -> AnyView)? = nil,
        selectedElementOutputContent: ((KeypadElementInputID) -> AnyView)? = nil,
        connectedDeviceInfo: ControllerClientDeviceInfo? = nil,
        externallyPressedElementInputs: Set<KeypadElementInputID> = [],
        editorDeliveryStatusText: String? = nil,
        onTestElementInputChanged: ((KeypadElementInputID, Bool) -> Void)? = nil,
        onTestElementInputTap: ((KeypadElementInputID, Int) -> Void)? = nil
    ) {
        let loadedProfiles: GamepadConfigurationProfilePersistence.LoadedState
        if let initialProfiles {
            loadedProfiles = GamepadConfigurationProfilePersistence.normalizedState(
                profiles: initialProfiles,
                activeProfileID: initialSelectedProfileID,
                defaultProfileID: initialDefaultProfileID,
                fallbackCustomization: customization.wrappedValue
            )
        } else {
            loadedProfiles = GamepadConfigurationProfilePersistence.load(
                activeCustomization: customization.wrappedValue
            )
        }

        let initialCustomization = customization.wrappedValue.normalized

        self._externalCustomization = customization
        self._customization = State(initialValue: initialCustomization)
        self._editorLayerModel = State(initialValue: GamepadEditorLayerModel(customization: initialCustomization, defaultLabelProvider: defaultLabelProvider))
        self._cachedLayoutQualityReport = State(
            initialValue: initialCustomization.layoutQualityReport(
                profileName: loadedProfiles.activeProfile?.name,
                canvasSize: initialCustomization.deviceCanvas.editorDeviceFrame.screenRect.size
            )
        )
        self.showsPreview = showsPreview
        self.externalProfiles = initialProfiles
        self.externalSelectedProfileID = initialSelectedProfileID
        self.externalDefaultProfileID = initialDefaultProfileID
        self.onReset = onReset
        self.onProfilesChanged = onProfilesChanged
        self.onExportProfiles = onExportProfiles
        self.onImportProfiles = onImportProfiles
        self.onRegisterProfileUndoSnapshot = onRegisterProfileUndoSnapshot
        self.onLaunchProfileTarget = onLaunchProfileTarget
        self.defaultLabelProvider = defaultLabelProvider
        self.profileOutputModeContent = profileOutputModeContent
        self.selectedElementOutputContent = selectedElementOutputContent
        self.connectedDeviceInfo = connectedDeviceInfo
        self.externallyPressedElementInputs = externallyPressedElementInputs
        self.editorDeliveryStatusText = editorDeliveryStatusText
        self.onTestElementInputChanged = onTestElementInputChanged
        self.onTestElementInputTap = onTestElementInputTap
        self._selectedControlID = State(initialValue: .builtin(.jump))
        self._selectedControlIDs = State(initialValue: [])
        self._isControlSelectionActive = State(initialValue: false)
        self._profiles = State(initialValue: loadedProfiles.profiles)
        self._selectedProfileID = State(initialValue: loadedProfiles.activeProfileID)
        self._selectedProfileIDs = State(initialValue: [])
        self._draggingProfileIDs = State(initialValue: [])
        self._defaultProfileID = State(initialValue: loadedProfiles.defaultProfileID)
        self._selectedProfileOrientation = State(initialValue: loadedProfiles.activeProfile?.customization.deviceCanvas.editorDeviceFrame.orientation ?? .landscape)
        self._isSelectedProfileExpanded = State(initialValue: true)
        self._selectedProfileNameDraft = State(initialValue: loadedProfiles.activeProfile?.name ?? "Current Setup")
        self._expandedLayerGroupIDs = State(initialValue: [])
        self._layerSelectionAnchorID = State(initialValue: nil)
        self._expandedInspectorSections = State(initialValue: [.selectedElementIdentity, .selectedElementPosition, .keypadDevice])
    }

    private var activeDeviceFrame: GamepadEditorDeviceFrame {
        customization.deviceCanvas.editorDeviceFrame
    }

    private var activeDesignCanvasSize: CGSize {
        activeDeviceFrame.screenRect.size
    }

    private var connectedDeviceFrame: GamepadEditorDeviceFrame? {
        guard let connectedDeviceInfo else { return nil }
        return GamepadEditorDeviceCatalog.suggestedFrame(
            for: connectedDeviceInfo,
            preferredOrientation: activeDeviceFrame.orientation
        )
    }

    private var editorColorScheme: GamepadEditorColorScheme {
        GamepadEditorColorScheme(rawValue: editingColorSchemeRawValue) ?? .system
    }

    private var activeKeypadColorScheme: ColorScheme {
        switch editorColorScheme {
        case .system:
            return customization.resolvedColorScheme(system: connectedDeviceSystemColorScheme ?? colorScheme)
        case .light:
            return .light
        case .dark:
            return .dark
        }
    }

    private var connectedDeviceSystemColorScheme: ColorScheme? {
        switch connectedDeviceInfo?.interfaceStyle?.lowercased() {
        case "light": return .light
        case "dark": return .dark
        default: return nil
        }
    }

    private var controlBarPreviewContext: GamepadControlBarPreviewContext {
        let trimmedProfileName = selectedProfileNameDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        return GamepadControlBarPreviewContext(
            profileName: trimmedProfileName.isEmpty ? (selectedProfile?.name ?? "Current Setup") : trimmedProfileName,
            hasProfiles: !profiles.isEmpty,
            isSelectedProfileDefault: selectedProfileID == defaultProfileID,
            launchTarget: selectedProfile?.launchTarget,
            isConnected: connectedDeviceInfo != nil
        )
    }

    private var editorColorSchemeBinding: Binding<GamepadEditorColorScheme> {
        Binding(
            get: { editorColorScheme },
            set: { editingColorSchemeRawValue = $0.rawValue }
        )
    }

    private var profileOrientationPreferenceBinding: Binding<GamepadProfileOrientationPreference> {
        Binding(
            get: { selectedProfile?.orientationPreference ?? .automatic },
            set: { setSelectedProfileOrientationPreference($0) }
        )
    }

    private var profileImportNoticePresented: Binding<Bool> {
        Binding(
            get: { profileImportNotice != nil },
            set: { isPresented in
                if !isPresented { profileImportNotice = nil }
            }
        )
    }

    private var resourceLibraryNoticePresented: Binding<Bool> {
        Binding(
            get: { resourceLibraryNotice != nil },
            set: { isPresented in
                if !isPresented { resourceLibraryNotice = nil }
            }
        )
    }

    private func makeEditorLayerModel(for customization: GamepadCustomization) -> GamepadEditorLayerModel {
        GamepadEditorLayerModel(customization: customization, defaultLabelProvider: defaultLabelProvider)
    }

    private func setEditorCustomization(_ normalizedCustomization: GamepadCustomization) {
        customization = normalizedCustomization
        editorLayerModel = makeEditorLayerModel(for: normalizedCustomization)
        refreshLayoutQualityReport(for: normalizedCustomization)
    }

    private func refreshLayoutQualityReport(for customization: GamepadCustomization) {
        cachedLayoutQualityReport = customization.layoutQualityReport(
            profileName: selectedProfile?.name,
            canvasSize: customization.deviceCanvas.editorDeviceFrame.screenRect.size
        )
    }

    private var deviceFrameAnimation: Animation? {
        accessibilityReduceMotion ? .easeInOut(duration: 0.16) : Self.deviceFrameSpringAnimation
    }

    var body: some View {
        presentedEditor
    }

    private var editorCore: some View {
        VStack(spacing: 0) {
            if showsPreview {
                editorCommandBar
                Divider()
            }

            Group {
                if showsPreview {
                    GeometryReader { proxy in
                        if proxy.size.width >= 900 {
                            wideEditor
                        } else {
                            compactEditor
                        }
                    }
                } else {
                    ScrollView(.vertical, showsIndicators: true) {
                        inspectorCompactSection
                            .padding(Geist.Spacing.s4)
                    }
                }
            }
        }
        .overlayPreferenceValue(GamepadEditorOnboardingTargetPreferenceKey.self) { anchors in
            GeometryReader { proxy in
                if let step = activeFirstKeypadOnboardingStep {
                    GamepadEditorFirstKeypadOverlay(
                        step: step,
                        targetRect: anchors[step.target].map { proxy[$0] },
                        containerSize: proxy.size,
                        onPrevious: retreatFirstKeypadOnboarding,
                        onNext: advanceFirstKeypadOnboarding,
                        onSkip: completeFirstKeypadOnboarding
                    )
                    .transition(.opacity.combined(with: .scale(scale: 0.985)))
                }
            }
            .allowsHitTesting(activeFirstKeypadOnboardingStep != nil)
        }
        .animation(accessibilityReduceMotion ? .easeInOut(duration: 0.16) : .spring(response: 0.34, dampingFraction: 0.88), value: activeFirstKeypadOnboardingStep)
        .onChange(of: observedExternalProfiles) { _, _ in
            syncExternalProfileState()
        }
        .onChange(of: externalSelectedProfileID) { _, _ in
            syncExternalProfileState()
        }
        .onChange(of: externalDefaultProfileID) { _, _ in
            syncExternalProfileState()
        }
        .onChange(of: externalCustomization) { _, newValue in
            syncExternalCustomizationState(newValue)
        }
        .onAppear {
            applyConnectedDeviceFrameIfAvailable()
            applySelectedProfileCustomizationForCurrentOrientation()
            presentFirstKeypadOnboardingIfNeeded()
        }
        .onChange(of: isFirstKeypadOnboardingReplayRequested) { _, requested in
            if requested {
                hasCompletedFirstKeypadOnboarding = false
                presentFirstKeypadOnboardingIfNeeded()
            }
        }
        .onChange(of: customization.deviceCanvas) { _, _ in
            selectedProfileOrientation = activeDeviceFrame.orientation
            noteCanvasLayoutSize(width: activeDesignCanvasSize.width, height: activeDesignCanvasSize.height)
            draftCanvasZoom = nil
            canvasZoomValue = 1
            isCanvasFitMode = true
        }
        .onChange(of: connectedDeviceInfo) { _, _ in
            applyConnectedDeviceFrameIfAvailable()
        }
        .onChange(of: componentListItems.count) { _, newCount in
            if newCount > 0 {
                completeFirstKeypadOnboarding()
            }
        }
        .onChange(of: selectedControlID) { _, _ in
            if selectedControlIsEditable {
                expandedInspectorSections.insert(.selectedElementIdentity)
                expandedInspectorSections.insert(.selectedElementPosition)
            }
        }
        .onChange(of: interactionMode) { oldMode, newMode in
            if oldMode == .test && newMode != .test {
                releaseAllTestInputs()
            }
            if newMode == .test {
                activeCanvasTool = .select
                isControlSelectionActive = false
                selectedControlIDs.removeAll()
                announceEditor("Test mode. Keypad controls send their configured outputs.")
            } else {
                announceEditor("Edit mode. Keypad controls can be selected and arranged.")
            }
        }
        .onChange(of: editorDeliveryStatusText) { _, status in
            guard let status, status.localizedCaseInsensitiveContains("fail") || status.localizedCaseInsensitiveContains("offline") else { return }
            announceEditor(status)
        }
        .onReceive(NotificationCenter.default.publisher(for: NSApplication.didResignActiveNotification)) { _ in
            releaseAllTestInputs()
            finishActiveContinuousEdit()
            commitPendingEditorChanges()
        }
        .onReceive(NotificationCenter.default.publisher(for: .thumbleCommitPendingEditorChanges)) { _ in
            releaseAllTestInputs()
            finishActiveContinuousEdit()
            commitPendingEditorChanges()
            commitSelectedProfileNameDraft()
        }
        .onChange(of: isProfileNameFieldFocused) { _, isFocused in
            if !isFocused {
                commitSelectedProfileNameDraft()
            }
        }
        .background {
            GamepadEditorKeyboardShortcutBridge(
                onDelete: deleteSelectedControl,
                onUndo: performUndo,
                onRedo: performRedo,
                onGroup: performGroupShortcut,
                onUngroup: performUngroupShortcut,
                onDuplicate: duplicateSelectedControls,
                onSelectAll: selectAllVisibleControls,
                onQuickBind: beginQuickBindSelectedControl,
                onShowShortcuts: { isShortcutReferencePresented = true; return true },
                onEscape: handleEditorEscape,
                onZoom: handleZoomShortcut,
                onTool: activateCanvasTool,
                onNudge: nudgeSelectedControls
            )
            .frame(width: 0, height: 0)
        }
    }

    private var presentedEditor: some View {
        editorCore
        .sheet(isPresented: $isResourceLibraryPresented) {
            resourceLibrarySheet
                .frame(minWidth: 720, idealWidth: 820, minHeight: 500, idealHeight: 580)
        }
        .fileImporter(
            isPresented: $isStyleLibraryImporterPresented,
            allowedContentTypes: [.json],
            allowsMultipleSelection: false,
            onCompletion: handleStyleLibraryImport
        )
        .fileExporter(
            isPresented: $isStyleLibraryExporterPresented,
            document: styleLibraryExportDocument,
            contentType: .json,
            defaultFilename: "Thumble-Styles.json"
        ) { result in
            if case .failure(let error) = result,
               (error as? CocoaError)?.code != .userCancelled {
                resourceLibraryNotice = error.localizedDescription
            }
        }
        .fileImporter(
            isPresented: $isAssetImporterPresented,
            allowedContentTypes: [.image, .data],
            allowsMultipleSelection: false,
            onCompletion: handleAssetImport
        )
        .fileImporter(
            isPresented: $isProfileImporterPresented,
            allowedContentTypes: [.json],
            allowsMultipleSelection: false,
            onCompletion: handleProfileImport
        )
        .alert(
            "Import Keypad Setups",
            isPresented: profileImportNoticePresented
        ) {
            Button("OK", role: .cancel) { profileImportNotice = nil }
        } message: {
            Text(profileImportNotice ?? "Import complete.")
        }
        .alert(
            "Keypad Resources",
            isPresented: resourceLibraryNoticePresented
        ) {
            Button("OK", role: .cancel) { resourceLibraryNotice = nil }
        } message: {
            Text(resourceLibraryNotice ?? "Resource update complete.")
        }
        .sheet(isPresented: $isShortcutReferencePresented) {
            shortcutReferenceSheet
                .frame(minWidth: 560, idealWidth: 640, minHeight: 470, idealHeight: 560)
        }
        .sheet(isPresented: $isOrientationComparisonPresented) {
            orientationComparisonSheet
                .frame(minWidth: 860, idealWidth: 1040, minHeight: 540, idealHeight: 680)
        }
        .confirmationDialog(
            "Create the missing \(pendingOrientationChange?.frame.orientation.displayName.lowercased() ?? "orientation") layout",
            isPresented: Binding(
                get: { pendingOrientationChange != nil },
                set: { if !$0 { pendingOrientationChange = nil } }
            ),
            titleVisibility: .visible
        ) {
            Button("Copy Current Layout") { completePendingOrientationChange(automaticallyArranged: false) }
            Button("Arrange Automatically") { completePendingOrientationChange(automaticallyArranged: true) }
            Button("Cancel", role: .cancel) { pendingOrientationChange = nil }
        } message: {
            Text("Portrait and landscape are saved separately. You can copy the current positions exactly or create a rotated first pass and review its layout suggestions.")
        }
        .alert(
            "Couldn’t Complete Editor Action",
            isPresented: Binding(
                get: { editorOperationError != nil },
                set: { if !$0 { editorOperationError = nil } }
            )
        ) {
            Button("OK", role: .cancel) { editorOperationError = nil }
        } message: {
            Text(editorOperationError ?? "The requested editor action could not be completed.")
        }
        .alert(
            "Rename Layer Group",
            isPresented: Binding(
                get: { groupRenameTargetID != nil },
                set: { if !$0 { groupRenameTargetID = nil } }
            )
        ) {
            TextField("Group name", text: $groupRenameDraft)
            Button("Rename") { commitGroupRename() }
            Button("Cancel", role: .cancel) { groupRenameTargetID = nil }
        } message: {
            Text("Choose a name that describes the controls in this group.")
        }
        .onDisappear {
            releaseAllTestInputs()
            finishActiveContinuousEdit()
            commitPendingEditorChanges()
        }
    }

    private var editorCommandBar: some View {
        GeometryReader { proxy in
            Group {
                if proxy.size.width >= 1_160 {
                    editorCommandBarFullContent
                } else {
                    editorCommandBarCompactContent
                }
            }
            .frame(width: proxy.size.width, height: proxy.size.height)
        }
        .frame(height: min(max(editorCommandBarHeight, 48), 80))
        .background(Geist.color(.background100, scheme: colorScheme))
    }

    private var editorCommandBarFullContent: some View {
        HStack(spacing: Geist.Spacing.s2) {
                if shouldShowCommandBarProfileSwitcher {
                    commandBarProfileSwitcher
                }

                Picker("Mode", selection: $interactionMode) {
                    ForEach(GamepadEditorInteractionMode.allCases) { mode in
                        Label(mode.displayName, systemImage: mode.systemImage).tag(mode)
                    }
                }
                .pickerStyle(.segmented)
                .labelsHidden()
                .frame(width: 132)
                .help(interactionMode == .edit ? "Edit controls on the canvas" : "Press controls to send their real outputs")

            Divider().frame(height: 24)

            commandBarIconButton(
                systemImage: "arrow.uturn.backward",
                label: "Undo",
                isDisabled: !(undoManager?.canUndo ?? false),
                action: { _ = performUndo() }
            )
            commandBarIconButton(
                systemImage: "arrow.uturn.forward",
                label: "Redo",
                isDisabled: !(undoManager?.canRedo ?? false),
                action: { _ = performRedo() }
            )

            addControlMenu
                .disabled(interactionMode == .test)

            if isControlSelectionActive && interactionMode == .edit {
                commandBarIconButton(
                    systemImage: "keyboard.badge.ellipsis",
                    label: "Quick Bind",
                    isDisabled: !canQuickBindSelectedControl,
                    action: { _ = beginQuickBindSelectedControl() }
                )
                commandBarIconButton(
                    systemImage: "plus.square.on.square",
                    label: "Duplicate",
                    isDisabled: !canDuplicateSelectedControls,
                    action: { _ = duplicateSelectedControls() }
                )
                commandBarIconButton(
                    systemImage: "trash",
                    label: "Delete",
                    isDisabled: false,
                    action: { _ = deleteSelectedControl() }
                )
            }

            orientationWorkflowMenu

            layoutQualityMenu

            Spacer(minLength: Geist.Spacing.s2)

            if interactionMode == .test, let lastTestActionText {
                Label(lastTestActionText, systemImage: "waveform")
                    .geistTypography(.label12)
                    .foregroundStyle(Geist.color(.gray900, scheme: colorScheme))
                    .lineLimit(1)
                    .frame(maxWidth: 180)
            }

            Label(editorSaveAndSyncStatusText, systemImage: editorSaveAndSyncStatusImage)
                .geistTypography(.label12)
                .foregroundStyle(Geist.color(.gray900, scheme: colorScheme))
                .lineLimit(1)
                .help(editorSaveAndSyncStatusText)

            HStack(spacing: 2) {
                commandBarIconButton(systemImage: "minus", label: "Zoom Out", isDisabled: effectiveCanvasZoom <= Self.canvasZoomMin + 0.001) {
                    changeCanvasZoom(by: -0.10)
